// patterns.js — the "clue → pattern" teaching layer.
//
// The gallery teaches how to SOLVE each problem; this layer teaches how to
// RECOGNISE which technique a new problem needs — the transferable skill.
//
//   PATTERNS — the canonical technique taxonomy. `tell` is the general signal in
//     a problem statement that points to the technique (shown in the filter/index
//     and on hover). `order` fixes the filter-bar order (algorithmic first).
//   SPOT — per challenge id → { pattern, spot }. `pattern` keys into PATTERNS
//     (the eyebrow label + the filter spine); `spot` is the problem-specific clue
//     rendered under the statement. Every challenge needs an entry here — a
//     missing one silently degrades to "Direct" with no clue box.
//
// One central file instead of editing 32 challenge modules — and it doubles as a
// single reviewable index of every pattern and clue.

export const PATTERNS = {
  "Backtracking": { order: 1, tell: `Return <b>every</b> combination or arrangement, and each step is a choice you can undo. Build a partial answer, recurse, and unwind on a dead end.` },
  "Dynamic programming": { order: 2, tell: `Count the number of <b>ways</b>, or the best value, when subproblems overlap and pieces are reused. Fill a table bottom-up so nothing is recomputed.` },
  "Greedy": { order: 3, tell: `Serve or choose as much as possible under a constraint, where committing to the <b>locally-best</b> option first turns out globally optimal.` },
  "Recursion": { order: 4, tell: `The data is <b>self-similar or nested</b> — parentheses, a schema, a tree. Solve it by solving smaller copies of itself.` },
  "Hashing": { order: 5, tell: `You keep asking <b>"have I seen this?"</b> Build a set/map once and trade memory for O(1) membership and dedup.` },
  "Flood fill": { order: 6, tell: `A <b>connected region</b> on a grid. Spread out from a seed cell to every like-valued neighbour (BFS/DFS).` },
  "Math": { order: 7, tell: `There's a <b>closed-form formula</b> or a divisibility/factor structure — reach for arithmetic or a √n trick instead of brute enumeration.` },
  "Simulation": { order: 8, tell: `No shortcut — just <b>run the process</b> the problem describes, step by step, until it reaches a stopping state.` },
  "Gotcha": { order: 9, tell: `The obvious one-liner looks right but is <b>subtly wrong</b> — a built-in's default behaviour bites (e.g. lexicographic sort).` },
  "Direct": { order: 10, tell: `<b>No hidden trick.</b> Translate the spec straight into code — a scan, a filter, a lookup, or a chain of conditionals. Recognising there's no clever pattern is itself a skill: it stops you over-engineering.` },
};

export const SPOT = {
  "combination-sum": { pattern: "Backtracking", spot: `The prompt asks for <b>every</b> combination that sums to a target, with numbers reusable — each pick is a choice you can take back. <b>"All the ways to build X"</b> is the backtracking tell.` },
  "anagram":         { pattern: "Hashing", spot: `"The same characters in any order" is a promise that <b>order is noise</b> — so any solution still looking at position is answering a harder question than the one asked. Strip the property the problem says to ignore and what is left is a <b>multiset</b>, which means counting, which means a map. The reason this is the Hashing tell and not a sorting one is what happens when you scale the question: sorting both sides re-derives the whole ordering to throw it away again, while the tally answers "is this letter still available?" in O(1) and keeps working for "is str2 a sub-anagram of str1" or a stream you cannot re-read. Two clauses then decide the code. <b>"Ignore casing and white space"</b> is a <i>normalisation</i>, not a comparison rule — do it once at the boundary and every later line gets simpler, rather than sprinkling <code class='inl'>toLowerCase</code> through the compare. And the <b>length guard is free</b>: unequal lengths can never be a rearrangement, so it settles a whole class of inputs before any counting starts. The subtle bit is that <b>you must decrement, not delete</b> — treat the tally as a set of seen letters and <code class='inl'>"aab"</code> matches <code class='inl'>"abb"</code>, which no official test catches.` },
  "targetsum":       { pattern: "Hashing", spot: `The giveaway is that the two things you are hunting are <b>not independent</b>: fix one and the equation <i>names</i> the other. <code class='inl'>a + b = target</code> means once you are standing on <code class='inl'>arr[i]</code>, the partner is not something to search for — it is <code class='inl'>target - arr[i]</code>, a value you can compute. That collapses the whole inner loop into a single question, <b>"have I seen this number before?"</b>, which is the Hashing tell in its purest form. The general rule worth carrying away: whenever a nested loop's inner condition can be <b>solved</b> for the inner variable, the inner loop is a lookup wearing a loop's clothes. Two problem-specific details then fall out for free rather than needing code. Checking the map <b>before</b> inserting the current value is what stops a number pairing with itself — no <code class='inl'>i !== j</code> test needed. And because the map only ever holds indices you have already walked past, <code class='inl'>seen.get(need)</code> is always smaller than <code class='inl'>i</code>, so <b>"indices in ascending order"</b> is satisfied without a sort or a swap. Read the not-found clause carefully too: it returns a <b>string</b>, not an empty array, so the return type is a union and <code class='inl'>assert.deepEqual</code> will not save you.` },
  "factorial":       { pattern: "Math", spot: `The recurrence <code class='inl'>n! = n × (n−1)!</code> makes this the textbook recursion example, and that is the trap — it is a <b>fold</b>, not a tree. There is one subproblem per level and no branching, so a recursive version buys nothing but stack frames; carry a running product instead. Two lines then do all the real work, and both are about <b>identity elements</b>: seed at <code class='inl'>1</code>, not 0, because 1 is the <b>empty product</b> (the same reason an empty sum seeds at 0) — that is what makes <b>0! = 1</b> fall out of the arithmetic rather than needing an <code class='inl'>if</code>. And start the loop at <code class='inl'>i = 2</code>, since multiplying by 1 is a no-op and skipping it makes 0! and 1! both return the seed from a loop body that never runs. The clue worth generalising is elsewhere, though: <b>when a problem states an odd, specific domain — "from zero to 20" — that bound is usually about the representation, not the algorithm.</b> Nothing about the loop changes at 21. What changes is that 20! is already <b>larger than <code class='inl'>Number.MAX_SAFE_INTEGER</code></b> and still exact (n! ends in enough binary zeros that the significand still fits), and <b>23!</b> is the first one a double gets wrong. A stated ceiling on a growth problem is a hint about where the number type gives out.` },
  "sumsquares":      { pattern: "Math", spot: `"The sum of the first n <i>somethings</i>" where the something is a <b>fixed polynomial in i</b> is the signal for a closed form — sums of a degree-<i>d</i> polynomial are always a degree-<i>(d+1)</i> polynomial, so 1² + 2² + … + n² has to be a cubic, and it is: <code class='inl'>n(n+1)(2n+1)/6</code>. The stated ceiling is the interesting part of the tell. <b>"Up to 1,000" is small enough that the loop is completely fine</b>, which is exactly why it is worth noticing that the loop is not <i>needed</i> — the problem is sized so that both approaches pass, and the difference is one you have to go looking for rather than one the grader forces on you. Two sanity checks keep the formula honest. It never produces a fraction, and not by luck: one of <code class='inl'>n</code> and <code class='inl'>n + 1</code> is even, and exactly one of the three factors is a multiple of 3, so the product always carries the 2 and the 3 that the /6 needs. And the growth is cubic rather than quadratic, which is the quick way to remember that the answer at n = 1,000 is in the hundreds of millions, not the millions.` },
  "threestrikes":    { pattern: "Direct", spot: `Read what the predicate is actually about: <b>a digit</b>. Not divisibility, not a remainder, not a factor — the <b>decimal spelling</b> of <code class='inl'>i²</code>. That distinction is the whole tell, because arithmetic properties have structure you can exploit and spelling does not. Knowing whether 37² contains a 3 tells you <b>nothing</b> about 38², so there is no sieve, no memo, no stride, and no closed form to find — <code class='inl'>String(i * i).includes("3")</code> really is the answer, and recognising that <i>quickly</i> is the skill the problem is testing. The counterpart trap is over-reading <b>"at least one"</b>: it makes the per-candidate result a <b>boolean</b>, so a square with two 3s in it is still one strike and <code class='inl'>includes</code> is the right method rather than a count. The stated ceiling of 10,000 is doing the same job as the one in <b>#9</b> — it is small enough to guarantee the honest scan finishes, which is the problem-setter quietly confirming there is no shortcut you are missing.` },
  "milepace":        { pattern: "Direct", spot: `A formatted value goes in and the <b>same format</b> comes out, which is precisely what makes the naive move tempting and wrong: dividing the minutes and the seconds separately. Neither half divides cleanly on its own and the leftovers have nowhere to live. The transferable rule is <b>collapse to a single base unit at the boundary, do every piece of arithmetic there, and re-format only on the way out</b> — the same shape as money in cents or angles in radians. Two details are problem-specific and both are about <i>where</i> the rounding goes. Round the <b>total seconds</b>, before the split, and the remainder can never reach 60; round after the split and you can manufacture <code class='inl'>"04:60"</code>, which is not a time. And use <code class='inl'>Math.floor</code> for the minutes rather than <code class='inl'>Math.round</code>, because the leftover belongs to the seconds. Finally, <b>"add leading zeros when needed"</b> is not a branch — it is <code class='inl'>padStart(2, "0")</code>, and it is worth testing on purpose, because none of the official cases produces a single-digit <i>seconds</i> value.` },
  "decoder":         { pattern: "Math", spot: `<b>"After Z it wraps back to A"</b> is the same structural tell as the zodiac wheel in <b>#336</b>: once a space is <b>circular</b>, positions are arithmetic mod 26 and the obvious walk — step the letter round one place at a time — is doing by hand what one subtraction already knows. Getting there is two moves. Subtract the base (<code class='inl'>65</code> for uppercase, <code class='inl'>97</code> for lowercase) to turn a character code into a <b>ring position 0–25</b>; that single step is also what preserves the case, because re-adding the same base at the end can only land you back in the case you started from. Then <b>decoding is the inverse of encoding</b> — subtract the shift rather than adding it — and a negative shift needs no branch at all, since subtracting a negative already walks the other way. The one genuinely JavaScript-specific trap is the wrap itself: <code class='inl'>%</code> in JS is a <b>remainder, not a modulo</b>, and it keeps the sign of the left operand, so <code class='inl'>-19 % 26</code> is <code class='inl'>-19</code> and not <code class='inl'>7</code>. The idiom <code class='inl'>((x % n) + n) % n</code> exists for exactly this and costs nothing when <code class='inl'>x</code> was already in range. Whenever a wrap-around problem passes the forward cases and fails the backward one, this is why.` },
  "unprime":         { pattern: "Math", spot: `The extra rule is a <b>symmetry</b>, not a rule. "A negative prime is the negative version of a positive prime" says the answer is unchanged by the sign — and an invariant is something to <b>normalise away at the boundary</b>, not to encode. One <code class='inl'>Math.abs</code> on line 1 and the word "negative" never appears again; branch on the sign instead and you are maintaining two copies of the same test. What is left is textbook trial division, and its one real idea is the <b>bound</b>. Divisors come in pairs: if <code class='inl'>m = a × b</code> with <code class='inl'>a &gt; √m</code> then <code class='inl'>b &lt; √m</code>, so every candidate above √m is the larger half of a pair whose smaller half was already tried and rejected. Reaching √m is therefore a <i>proof</i> that nothing is there, not a heuristic — which is why the loop can stop rather than merely slow down. Two details fall out. The early return makes a <b>composite</b> cheap and a <b>prime</b> the worst case, so the expensive inputs are exactly the ones that answer <code class='inl'>true</code>. And skipping the evens costs one line and buys the one special case worth remembering: <code class='inl'>m % 2 === 0</code> must return <code class='inl'>m === 2</code>, not <code class='inl'>false</code>.` },
  "battle":          { pattern: "Direct", spot: `Five return values are listed as if they were peers, and they are not — they are a <b>ladder</b> in the order given. The first two are decided by <code class='inl'>length</code> <i>before</i> any character is scored, so an army that would win every single battle still retreats for being one character short. That inversion is the whole problem: read "the army with more victories wins" as the headline rule and the retreat cases become special cases bolted on afterwards, in the wrong order. Once the lengths match, <b>"each character can only fight one battle"</b> is not a matching problem — it is index-for-index pairing, which is why no sorting or greedy assignment belongs anywhere near this. Then the printed strength table has one <b>collision</b> worth spotting before you write anything: digits score their face value and "all other characters" score zero, so <code class='inl'>'0'</code> and <code class='inl'>'@'</code> are indistinguishable and can never beat each other. Last, count <b>victories, not strength</b>, and let a tie score for nobody — the two tallies then need not add up to the number of battles, and an all-tie war reaches <code class='inl'>"It was a tie"</code> through the same line as a 3–3 one.` },
  "camelcase":       { pattern: "Direct", spot: `Split, transform, join — the shape is obvious, so the problem is entirely in two clauses of the statement. <b>"One or more characters"</b> makes a <i>run</i> of separators a single break, which is the <code class='inl'>+</code> in <code class='inl'>/[ _-]+/</code>; without it <code class='inl'>"peg__leg"</code> becomes three pieces with an empty one wedged between them. And <b>"the rest of it lowercase"</b> decides every hard case: flatten the whole word <i>first</i>, then raise one character. Uppercase the initial and leave the tail alone and <code class='inl'>"FREE cODE cAMP"</code> comes back as <code class='inl'>"freeCODECAMP"</code> — it passes the easy cases, which is what makes it survive. The transferable habit is the third one: after any split on a separator class, ask what the <b>ends</b> produce. A leading or trailing separator yields <code class='inl'>""</code>, and here that empty string does not merely add a stray word — <code class='inl'>""[0]</code> is <code class='inl'>undefined</code> and <code class='inl'>.toUpperCase()</code> on it <b>throws</b>. No official case starts or ends on a separator, so nothing in the grader ever reaches that line.` },
  "revparen":        { pattern: "Recursion", spot: `"Innermost first, and then its result is part of the reversal around it" is a <b>recurrence</b> read aloud, and the tell for a stack is that the nesting is already in the input — you do not have to discover the structure, only to follow it. The obvious alternative is to keep rewriting the string: find an innermost pair (the <b>first</b> <code class='inl'>)</code> and the <b>last</b> <code class='inl'>(</code> before it, which is guaranteed to contain nothing), reverse it, splice it out, repeat. That is correct, and it re-copies the entire string once per pair, rescanning a prefix that nothing touched. The one-pass reading is better because of a small piece of algebra rather than a micro-optimisation: push an empty buffer on <code class='inl'>(</code>, append ordinary characters to whichever buffer is on top, and on <code class='inl'>)</code> pop the top, <b>reverse it, and append it to the buffer beneath</b>. The child therefore enters its parent <i>already reversed</i>, so the parent's own reversal flips it a second time — which is exactly the nesting rule, obtained for free rather than coded. The buffer at the bottom is the answer, and it is also the reason no depth counter is needed: <code class='inl'>stack.length</code> already is the depth.` },
  "unorder":         { pattern: "Direct", spot: `The title is the specification: precedence must not exist. That rules out the reflex — building the expression as text and handing it to anything that evaluates arithmetic — because every such thing knows that <code class='inl'>*</code> binds tighter and will answer a different question (<code class='inl'>1 + 2 * 3 + 4 * 5</code> is 27 normally and <b>65</b> here). What kills precedence is a <b>fold</b>: carry one accumulator that already <i>is</i> the whole expression so far, collapsed to a single number, so there is never a pending sub-expression left for anything to reorder. The second clause, <b>"repeat the operators as needed"</b>, is not a second loop either — it is <code class='inl'>operators[(i − 1) % operators.length]</code>, and the <code class='inl'>− 1</code> is because numbers are indexed from 1 in the loop while gaps are indexed from 0. That same modulo silently handles <b>more operators than gaps</b>, where the cycle simply never wraps. Then read the arithmetic literally: <code class='inl'>/</code> is real division and <code class='inl'>%</code> is a remainder that keeps the left operand's sign, so nothing truncates and a negative intermediate stays negative.` },
  "secondbest":      { pattern: "Direct", spot: `Three numbered clauses, and the numbering <b>is</b> the control flow — the trap is that clause 1 outranks affordability. "The second most expensive laptop if it is within your budget" fires even when the most expensive is comfortably affordable, so <code class='inl'>[2099, 1599, 1899, 1499]</code> under a 2200 budget answers <b>1899</b>. Paraphrase it as "the best one you can afford" and that single case breaks while every other one keeps passing, which is the shape of bug that survives review. Two preparations then make each rung a one-liner: <b>dedupe</b>, because "second most expensive" is about distinct <i>positions</i> and two identical laptops occupy one, and <b>sort descending</b>, after which rank 2 is index 1 and "the most expensive within budget" collapses into "the first entry that fits". Note where the grader cannot help you — the official set contains a duplicate case, but on it the two readings coincide (the undeduped second entry is over budget, so it falls through to rung 2 and lands on the same number), so a missing dedupe passes all five tests. Finally, rung 3 returns the literal number <code class='inl'>0</code>, which is what the <code class='inl'>?? 0</code> after a <code class='inl'>find</code> that came back <code class='inl'>undefined</code> is for.` },
  "candles":         { pattern: "Math", spot: `The statement hands you a seven-step worked example, which is an invitation to simulate — and simulating is correct, so the tell has to come from somewhere else. It is this: <b>the price of a trade never changes</b>. Recycling takes <code class='inl'>k</code> stubs and returns a candle that burns back into <b>one</b> stub, so each trade costs exactly <code class='inl'>k − 1</code> stubs, on the first round and the twentieth alike. A constant cost per unit of progress is the signal that a loop is a <b>division</b> in disguise; when the cost drifts with the state, it is not, and you simulate. The second half is a change of question. Every candle that ever exists burns exactly once, so the answer is not "how much did I burn" but <b>"how many candles existed"</b> — the ones you were given plus the ones you traded for — which turns a process into a count. That gives <code class='inl'>candles + ⌊(candles − 1) / (k − 1)⌋</code>, where the <b>− 1</b> is the stub that can never be spent: a run always ends holding between 1 and k − 1 of them, and reserving one up front is cheaper than testing for it at the end. Two things the loop still teaches better than the formula: the stubs from <i>new</i> candles rejoin the pool, and the remainder must be <b>carried</b> between rounds — drop it and <code class='inl'>burnCandles(7, 2)</code> comes to 12.` },
  "arrdupes":        { pattern: "Hashing", spot: `The phrase to catch is <b>"more than once"</b>. It reads as a counting question — and counting works, at the price of re-scanning the whole array once per element — but it is really a <b>threshold at two</b>, and you cross it the moment a value turns up for the second time. That reframing is the Hashing tell in its most everyday form: whenever an inner loop exists only to answer <b>"have I met this before?"</b>, it is a membership test wearing a loop's clothes, and membership is what a <code class='inl'>Set</code> answers in O(1). Note which way the pressure runs — the counting version is <i>correct</i>, so nothing about the answer tells you to change it; only the shape of the work does, and the 21-element official case makes that plain at <b>441</b> equality tests against <b>21</b> lookups. Two clauses of the statement then confirm the structure rather than complicate it. <b>"Only include one instance of each value"</b> is a dedupe requirement, which an array answers with an <code class='inl'>includes</code> guard scanning the results from inside the loop, and a set answers by doing nothing at all — <code class='inl'>add</code> is idempotent. And the empty case needs no branch of its own: two empty sets spread to <code class='inl'>[]</code> on their own. The one thing a set cannot hand back is <b>order</b>, which is exactly why <b>"sorted in ascending order"</b> is a separate final step and not something the pass can maintain — and it wants <code class='inl'>(a, b) =&gt; a - b</code>. The third official case is precisely the input that punishes a bare <code class='inl'>.sort()</code>: it answers <code class='inl'>[-6, 0, 2, 23, 4, 5]</code>, because as text <code class='inl'>"23"</code> sorts before <code class='inl'>"4"</code>. What the grader never tries is an <b>empty input</b> — worth checking by hand, though here both readings survive it.` },
  "hexgen":          { pattern: "Math", spot: `The tell is a single word in the statement: <b>random</b>. A spec that asks for a random value <i>subject to a constraint</i> is a sampling problem, and sampling problems come in exactly two shapes — draw from the easy distribution and <b>throw away</b> whatever violates the constraint, or reorder the draws so the constraint is <b>already satisfied</b> when you finish. Both are correct here; what separates them is whether the work has an upper bound, and what the bound costs. Before any of that, read the grader, because a random answer cannot be compared against a fixed one and these tests are therefore <b>property assertions</b> rather than equality checks. Three of the seven call <code class='inl'>generateHex</code> <b>twice</b> and <code class='inl'>assert.notEqual</code> the results, which quietly outlaws every fixed answer — including the <code class='inl'>"FF0000"</code> the statement itself prints as an example — along with any scheme that quantises the losing channels coarsely enough for two calls to collide. The second trap is one word long: the assertion is <code class='inl'>isAbove</code>, not <code class='inl'>isAtLeast</code>, so a <b>tie</b> fails exactly like a loss, and three independently drawn bytes tie far more often than intuition suggests. The constructive fix then reads as pure arithmetic: draw the two losers first from <code class='inl'>0–254</code> (<code class='inl'>× 255</code>, not <code class='inl'>× 256</code> — a loser of 255 leaves nothing above it), then draw the winner from <code class='inl'>[max + 1, 255]</code>, where the <b>+ 1</b> is "strictly above" encoded once into a range instead of retested on every attempt. It is not free, and this is the part worth carrying away: rejection sampling is exactly uniform over all 5,559,680 valid triples and construction is not, so bounding the work quietly skews the output — the colours come out measurably paler. Last, the boring assertion is the one that actually breaks solutions — <code class='inl'>assert.lengthOf(hex, 6)</code> means every channel needs <code class='inl'>padStart(2, "0")</code>, because a value below 16 is a single hex digit, and one call in six to eight has one.` },
  "tribonacci":      { pattern: "Dynamic programming", spot: `The recurrence is <b>handed to you</b> — "each number is the sum of the three preceding ones" — so the usual dynamic-programming question, <i>what is the subproblem</i>, is already answered and the only decision left is <b>recompute or remember</b>. The tell for remembering is that every operand <code class='inl'>T(i)</code> would need is an <i>earlier term of the very thing you were asked to return</i>. When the output is indexed by the same variable the recurrence is indexed by, the output array <b>is</b> the table: there is no memo to add and no cache to invalidate, only a forward pass that never reads a value it has not already written. That is also why the problem has no second approach — asking <code class='inl'>T(i)</code> index by index is not a rival mental model, it is declining to write into a table you are required to fill anyway (see <b>#3</b>, which is the same shape one term narrower and makes the same call). Price the instinct rather than tabbing to it: <code class='inl'>T(i) = T(i−1) + T(i−2) + T(i−3)</code>, asked once per index, is <b>correct</b> — it passes all six official tests — and costs 152,843 calls to produce twenty numbers, because nothing is written down between questions and the three subtrees overlap almost entirely. <code class='inl'>T(2)</code> gets worked out 42,762 separate times and answers the same number on every one of them. That is what "overlapping subproblems" means concretely — <b>one index reached by many paths</b> — and three terms rather than two grow the cost at <b>1.8393ⁿ</b> instead of φⁿ, which is why it is visible at length 20 here and only near 35 for Fibonacci. The other half of the problem is not the recurrence at all. The base case is an <b>argument</b> — you are handed the first three numbers — and <code class='inl'>length</code> counts <i>everything</i>, seeds included, so at length 1 the correct answer is <b>shorter than the input you were given</b>. Four of the six official tests sit at lengths 0, 1, 2 and 3: the grader is far more worried about truncation than about the sum. <code class='inl'>startSequence.slice(0, length)</code> clamps at both ends and settles all four in one call, while the instinctive <code class='inl'>[...startSequence]</code> has already overshot three of them before the loop is reached.` },
  "rgbhex":          { pattern: "Direct", spot: `Split, convert, join — the shape is so obvious that the difficulty must be somewhere else, and it is: two clauses of the statement, neither of them the arithmetic. The first is the <b>input type</b>. You are handed <code class='inl'>"rgb(1, 11, 111)"</code>, a <i>formatted string</i>, not three numbers — so reach for <code class='inl'>split(",")</code> and you inherit the <code class='inl'>rgb(</code> wrapper, the closing <code class='inl'>)</code> and the <b>space after every comma</b>, all of which then have to be trimmed back off. Ask for <code class='inl'>/\\d+/g</code> instead — runs of digits — and every one of them is stepped over for free, because none of them is a digit. That is the transferable habit: when the values you want are <i>embedded in</i> punctuation rather than merely separated by it, describe what you want rather than enumerating what you must remove. The second clause is <b>"a <code class='inl'>#</code> followed by six characters. Don't use any shorthand values"</b>, and it is not a formatting preference — it is the problem-setter naming the bug in advance. A byte is exactly two base-16 digits, <code class='inl'>⌊n / 16⌋</code> and <code class='inl'>n % 16</code>, but <code class='inl'>toString(16)</code> is <b>variable-width</b>: it returns the shortest form, so <code class='inl'>1</code> comes back as <code class='inl'>"1"</code> and a straight join hands you five characters that still read as a colour. <code class='inl'>padStart(2, "0")</code> is therefore not cosmetic — the zero it inserts <b>is</b> the high nibble, a digit that exists and was dropped. Watch where the grader can and cannot help: only one of freeCodeCamp's four cases has a channel below 16, so a missing pad passes three of four, and on <code class='inl'>rgb(0, 0, 0)</code> the unpadded <code class='inl'>"#000"</code> is legal CSS that a browser paints correctly while the test still fails. The lowercase rule, by contrast, is free — <code class='inl'>toString(16)</code> already emits <code class='inl'>a-f</code>; casing only bites in the other direction, on hex you were given.` },
  "pangram":         { pattern: "Hashing", spot: `The word <b>pangram</b> is a false friend, and noticing that is most of the work. It asks <i>does this text contain every letter?</i> — one direction — while the statement asks for that <b>and no other letters</b>, which is the other direction as well. What is being tested is <b>set equality</b>, and the one-directional read is not a near miss: it passes <b>6 of freeCodeCamp's 8 cases</b>, so the grader mostly agrees with you. The general tell is a statement whose last clause is a <i>prohibition</i> rather than a requirement — "and nothing else", "and no others", "exactly these" — because a prohibition is never discharged by checking the things you were handed; it is only discharged by checking the things you found. Then the hashing part. Both sides collapse to <b>sets</b>, because "at least once" says multiplicity carries no information — six a's and one a are the same input — which is exactly what rules out the tempting move of sorting both strings and comparing them. Sets give O(1) membership in each direction, so the whole check is two linear sweeps and the answer is their AND. Two details then decide the code. The normalisation — "ignore casing", "ignore non-alphabetical characters" — applies to the <b>sentence only</b>, since <code class='inl'>letters</code> arrives promised lowercase, so it belongs once at the boundary rather than sprinkled through the comparisons. And <code class='inl'>letters</code> is never promised <i>distinct</i>, so the shortcut <code class='inl'>used.size === letters.length</code> is wrong on <code class='inl'>("hello", "hello")</code> — put that side through a Set too and <code class='inl'>used.size === allowed.size</code> becomes a legitimate one-line stand-in for the second containment.` },
  "vowelrep":        { pattern: "Direct", spot: `<b>"one more time than the previous vowel"</b> is not a string rule, it is a <b>counter</b> — and every hard part of this problem is the counter's <b>scope</b>. Nothing in the statement says where it lives, so the default reading (declare it wherever you happen to be) quietly makes it per word, and <code class='inl'>"hello world"</code> comes back as <code class='inl'>"helloo woorld"</code>, one o short, passing every single-word test you would think to write. The tell that it spans the whole string is the phrase <i>the previous vowel you <b>encountered</b></i> — not "in this word", not "of this letter". One declaration outside the loop, advanced on a vowel <b>occurrence</b> and on nothing else: a consonant is not a smaller step, it is no step. The second half is a packing trick worth stealing. Three separate clauses govern case here — the original keeps its own, the copies are lowercase, non-vowels are untouched — which invites three branches, and three branches is three chances to be wrong. Write <code class='inl'>ch + ch.toLowerCase().repeat(seen++)</code> and all three become consequences of one expression: <code class='inl'>ch</code> is the original, <code class='inl'>ch.toLowerCase()</code> is the copy, and a non-vowel never enters the branch at all. When a spec lists rules that all concern the <i>same</i> value, look for the single expression that separates them rather than a branch per rule. Last, read the answer's <b>size</b> before writing anything: v vowels add <code class='inl'>0 + 1 + … + (v − 1)</code> characters, so the output is quadratic in the vowels while the input is linear. Nothing can beat that, because the answer is that big — which is itself the signal that there is no cleverness to hunt for, only clauses to read.` },
  "ipv4":            { pattern: "Gotcha", spot: `Every rule in the statement is about <b>characters</b>, and the tool you instinctively reach for reads <b>values</b>. "Only numeric characters" and "no leading zeros" are constraints on the text <code class='inl'>"01"</code>, not on the number 1 — so the moment you write <code class='inl'>Number(p) &gt;= 0 &amp;&amp; Number(p) &lt;= 255</code> you have discarded the only thing those two rules could have been checked against. <code class='inl'>Number</code> is deliberately generous: <code class='inl'>Number("01")</code> is 1, <code class='inl'>Number("")</code> is <b>0</b>, <code class='inl'>Number(" 7 ")</code> is 7, <code class='inl'>Number("0x1f")</code> is 31. Every one of those sits comfortably inside 0–255 while breaking a rule the range check can no longer see, and <b>three of freeCodeCamp's seven cases</b> fail in exactly that way. The sharpest is <code class='inl'>"192.168.101."</code>: <code class='inl'>split(".")</code> on a trailing dot returns <b>four</b> pieces, so the length check passes, and the fourth is <code class='inl'>""</code>, which numbers to 0 — two individually reasonable tests agreeing on the wrong answer. That is the transferable habit: whenever a spec constrains the <i>form</i> of a string and your first move is to parse it, ask what your parser is willing to forgive, because everything it forgives is a rule you have quietly stopped enforcing. The fix is an <b>ordering</b>, not a pile of special cases — match <code class='inl'>/^(0|[1-9]\\d*)$/</code> first, which rejects empty, non-numeric and leading-zero in one expression, and only then read the value. Note the alternation rather than a bare <code class='inl'>[1-9]</code> opener: <code class='inl'>0.0.0.0</code> is valid, so "no leading zeros" has to mean "<code class='inl'>0</code> alone is fine, <code class='inl'>0</code> followed by anything is not".` },
  "rotate":          { pattern: "Direct", spot: `Nothing here is hidden, and recognising that is the first move. A rotation names the destination of <b>every</b> cell as a closed-form function of its address — <code class='inl'>matrix[r][c]</code> goes to <code class='inl'>out[c][R−1−r]</code>, full stop — so there is nothing to search for, nothing to count, and no choice to make anywhere. That is the <b>Direct</b> tell in its purest form: when the answer's coordinates can be <i>written down</i> as an expression in the input's coordinates, you are not hunting an algorithm, you are getting one line right. The catch is that the one line is the hardest kind to review. <code class='inl'>out[c][R−1−r] = matrix[r][c]</code> has two subscripts that trade places and exactly one that is counted from the far end; put the <code class='inl'>R−1−</code> on the other one and the code still runs, still returns a matrix of the right shape, and quietly computes the <i>counter-clockwise</i> rotation instead. Notice how little help the grader is here — freeCodeCamp's <code class='inl'>[[0,1,0],[1,0,1],[0,0,0]]</code> holds two distinct values, so you cannot trace a cell by its contents and a wrong map reads as a perfectly good answer. So here is the habit worth carrying away: <b>when a transform is hard to verify as a single index expression, look for a decomposition into moves you already trust.</b> A clockwise rotation is exactly <i>transpose</i> followed by <i>reverse each row</i> — two named, familiar operations you can check by eye on a 3×3 you drew on paper, in place of one subscript nobody can check at all. The decomposition buys no time (both are one O(n²) pass, and for every n &gt; 1 the in-place version performs <i>more</i> cell writes); what it buys is O(1) extra space and reviewability. Three details then decide whether you get it right. <b>Order is not a detail</b> — transpose-then-reverse-rows is clockwise, reverse-rows-then-transpose is counter-clockwise, and getting it backwards is the classic bug precisely because both compile and both return a legitimate-looking matrix. The inner loop must start at <code class='inl'>c = r + 1</code>, because <code class='inl'>(r,c)</code> and <code class='inl'>(c,r)</code> are the <i>same pair</i>: walk the whole grid and every swap happens twice, handing back the original untouched. And the in-place form silently assumes a <b>square</b> — <code class='inl'>n = matrix.length</code> gets used as both dimensions, so a non-square does not throw, it comes back the wrong shape with the values scrambled. Every official case is square, so no test will tell you.` },
  "roman":           { pattern: "Direct", spot: `The statement hands you the rule outright — "if a smaller numeral appears before a larger one, the value is subtracted" — so there is nothing to discover, and the skill being tested is <b>reading what the rule is phrased in terms of</b>. It mentions a symbol and the one immediately after it. Nothing else. A rule stated over <b>adjacent elements</b> is a one-step lookahead, not a table of cases, and that is the whole solution: keep the seven values the problem gives you, add <code class='inl'>V[s[i]]</code>, and subtract it instead when <code class='inl'>V[s[i]] &lt; V[s[i+1]]</code>. The tell that you have drifted is very precise — <b>the moment you find yourself typing <code class='inl'>CM</code>, <code class='inl'>CD</code>, <code class='inl'>XC</code>, <code class='inl'>XL</code>, <code class='inl'>IX</code>, <code class='inl'>IV</code>, you are re-deriving by hand what one comparison computes.</b> That table is not wrong, and it is what most people write: thirteen rows probed top-down for the longest prefix, six of which are not symbols but transcribed special cases you have to remember, spell correctly, and order <i>above</i> their own first character — put <code class='inl'>C</code> before <code class='inl'>CM</code> and <code class='inl'>"CM"</code> silently parses as 100 + 1000 = 1100. The win is not asymptotic; both walk the string once and the input is a dozen characters. It is that six rules collapse into one, which is the kind of win that actually prevents bugs. Two details then fall out for free. Let the neighbour past the end default to <b>0</b> and the final symbol needs no special case, since every real value is at least 1 and so nothing can be smaller than the end of the string. And read the verb: the problem says <b>parse</b>, not <b>validate</b>. <code class='inl'>"IIII"</code> is supposed to return 4, not an error — building a validator you were never asked for is the classic scope creep here, and it is also the only thing that could make two correct parsers disagree. The case that punishes a careless reading is <code class='inl'>"DIV"</code>: scan D, I, V left to right adding as you go and you get 506, because the subtraction is buried in the middle rather than announcing itself at the front the way <code class='inl'>IV</code> does.` },
  "acronym":         { pattern: "Direct", spot: `The statement <b>enumerates</b> the words to ignore — <code class='inl'>a</code>, <code class='inl'>for</code>, <code class='inl'>an</code>, <code class='inl'>and</code>, <code class='inl'>by</code>, <code class='inl'>of</code>. Six strings, listed, closed. Almost everyone reads that as a <i>category</i> — "the little connecting words" — and the category contains <b>the</b>, so they quietly add it. freeCodeCamp tests exactly that: <code class='inl'>"By the way"</code> is <b>BTW</b>, not BW, and the long penguin sentence keeps both of its <code class='inl'>the</code>s. The habit worth carrying away is the general one: <b>when a spec enumerates a set, the set is the spec</b>, and an intuition about what the list is "for" is a different rule you invented. The second tell is about shape. This looks like a string problem and is really a <b>filter whose predicate depends on the index</b>: "ignore these words <i>unless they are the first word</i>" is not a property of the word, it is a property of the position. That is the one thing <code class='inl'>Array.prototype.filter</code> supports and people forget it supports — the callback's second argument — so <code class='inl'>filter((w, i) =&gt; i === 0 || !SKIP.has(w.toLowerCase()))</code> is the entire rule in one clause, with no pre-loop special case and therefore no off-by-one. Whenever a rule reads <b>"X, unless it is the first/last one"</b>, reach for the index argument rather than peeling the boundary off before the loop. Two smaller things decide whether the code is right. There are <b>two opposite case operations</b> in the same pipeline — <code class='inl'>toLowerCase()</code> to <i>match</i> a lowercase list, <code class='inl'>toUpperCase()</code> to <i>emit</i> the letter — and no official case capitalises a listed word, so the grader never punishes dropping the first one. And the free win of a <code class='inl'>Set</code> over an array <code class='inl'>includes</code> here is <b>not performance</b> at six words; it is <b>intent</b> — <code class='inl'>has</code> says <i>membership</i>, which is the word the statement itself uses.` },
  "unique":          { pattern: "Hashing", spot: `<b>"Are all of these different?"</b> is the purest form of <i>have I seen this before?</i>, and that question has exactly one good answer: write down what you have seen. The nested-loop version is what the same question looks like when you refuse to — for every character, re-walk everything after it, <code class='inl'>n(n−1)/2</code> comparisons to produce one boolean, every one of them re-deriving a fact an earlier position already had in its hands. The general tell worth carrying away: whenever an inner loop exists only to re-answer a <b>membership</b> question about elements you have already walked past, it is a lookup wearing a loop's clothes — the same observation that collapses two-sum, and here it collapses the whole inner loop into <code class='inl'>seen.has(ch)</code>. Two details are specific to this problem. The answer is a <b>boolean about the whole string</b> rather than a list, so the first collision ends the call — which is why the early return matters, and why the cost gap is <i>invisible</i> on exactly the cases you would reach for first: <code class='inl'>"hello"</code> is settled in 8 comparisons against 4 lookups and looks like nothing, while <code class='inl'>"QwErTy123!@"</code>, whose answer is <b>true</b>, pays all 55 against 11, because "nothing matched" can only be known after everything has been checked. Test only the strings that fail and you will never see the difference. And because it <i>is</i> a whole-string boolean, <code class='inl'>new Set(str).size === str.length</code> is a legitimate one-liner rather than a trick — you are comparing a <b>multiset's cardinality against a set's</b>, and any shortfall means something was counted twice. (Its one blind spot is units: <code class='inl'>Set</code> counts code points while <code class='inl'>.length</code> counts UTF-16 code units, so an emoji breaks it — no official case goes there.) Last, read "uppercase and lowercase letters should be considered different characters" for what it is: a stated rule that requires <b>no code at all</b>, because it is already how <code class='inl'>===</code> and <code class='inl'>Set</code> behave. The official <code class='inl'>"aA"</code> → <code class='inl'>true</code> case exists solely to catch someone who reflexively lowercased.` },
  "arraydiff":       { pattern: "Hashing", spot: `The giveaway is the phrase <b>"appear in only one of the arrays"</b>, and what matters about it is that it is <b>symmetric about its inputs</b> — swap the two arguments and the answer must not change. Asymmetric code cannot compute a symmetric function, so <code class='inl'>arr1.filter(x =&gt; !arr2.includes(x))</code> is not a near miss, it is a different question: that expression can only ever return values that were in <code class='inl'>arr1</code>. freeCodeCamp puts the proof in the first two official cases, which are the same pair swapped and both answer <code class='inl'>["cherry"]</code> — the one-way filter returns <code class='inl'>[]</code> on one of them and the right answer on the other. That is the general tell worth carrying away: <b>whenever a spec's phrasing is symmetric — "in only one", "in exactly one", "not shared by", "the difference between" — an asymmetric solution passes roughly half the tests</b>, which is the worst possible failure rate, because it reads as bad luck rather than as a design error. Two passes, then, not one, concatenated. The hashing is the cheap half of the idea rather than the clever half. Each pass asks the same question once per element — <b>"have I seen this value on the other side?"</b> — and <code class='inl'>includes</code> answers every one of those by rescanning the other array from the start, so the two loops together cost n×m. A <code class='inl'>Set</code> is that scan performed once and written down, which is what Hashing always is; you need <b>both</b> Sets, one per direction, for the same reason you need both passes. Two problem-specific details then fall out. <b>Duplicates are unspecified</b> — no official case repeats a value — and where you put the filter quietly rules on it: filtering the <i>arrays</i> (<code class='inl'>arr1.filter(…)</code>) keeps both copies, filtering the <i>Sets</i> (<code class='inl'>[...inA].filter(…)</code>) silently dedupes. That is a choice worth making on purpose rather than by accident. And the sort is a real requirement whose trap runs opposite to <b>#309 Number Sort</b>: there the bare <code class='inl'>.sort()</code> is the entire bug, while here it is <b>correct</b>, because the values are strings — just not for the reason it looks like. The default comparator orders by <b>UTF-16 code unit</b>, so every capital sorts ahead of every lowercase (<code class='inl'>"Z" &lt; "a"</code>); "alphabetical" and "what <code class='inl'>.sort()</code> does" coincide only while the data stays in one case, and no official case leaves a capital in the answer, so the grader never finds out.` },
  "revsentence":     { pattern: "Gotcha", spot: `Read the two bullets as a single sentence and the problem changes shape: words in the input "can be separated by <b>one or more</b> spaces", and the returned string "should only have <b>one space</b> between words". A statement that bothers to specify the separator twice, differently, is telling you the input and the output have <b>different whitespace shapes</b> — and that means the step doing real work is the <b>parse</b>, not the transform. The reversal is a one-liner in any language; the tokenisation is the entire challenge. Any solution that reaches for the separator as a <i>literal character</i> has already conceded the point, because <code class='inl'>split</code> with a string argument and <code class='inl'>split</code> with a regex argument are genuinely different functions wearing one name: only a regex can match a <b>run</b>. <code class='inl'>"a  b".split(" ")</code> is <code class='inl'>["a", "", "b"]</code>, and the empty string is not an error state — it is <code class='inl'>split</code> faithfully reporting that between two adjacent separators there was nothing. That is what makes it so hard to see: nothing threw, nothing returned <code class='inl'>undefined</code>, and the array is exactly right for the question that was actually asked. The empties then ride through <code class='inl'>reverse()</code> untouched, because re-ordering has no opinion about its elements, and each one buys a space back in <code class='inl'>join(" ")</code> — so <code class='inl'>"npm  install   apt    sudo"</code> comes back as <code class='inl'>"sudo    apt   install  npm"</code>, with the original runs <b>mirrored</b> onto the other end. <b>Two of freeCodeCamp's four cases</b> fail in exactly that way. The fix is <code class='inl'>/\\s+/</code>, and note that it is only <i>half</i> the fix: <code class='inl'>" a b".split(/\\s+/)</code> is still <code class='inl'>["", "a", "b"]</code>, because a run at position 0 has no word to its left and the match is forced to yield a zero-width piece, so <code class='inl'>trim()</code> is a second independent correction rather than tidying. The transferable habit is to treat "one or more" and "exactly one" appearing in the same statement as a <b>normalisation requirement</b>, and to ask of any splitter what it does with two separators in a row before trusting it with the middle of a pipeline.` },
  "screentime":      { pattern: "Direct", spot: `The statement is a <b>bulleted list of independent thresholds</b>, and that shape is itself the signal: there is no algorithm to find here, no structure to exploit, nothing that gets faster with a better container. The work is translating each bullet without dropping a word, and every bug in this problem is one of two words. The first is the comparison — "10 hours <b>or more</b>" is <code class='inl'>&gt;=</code>, and freeCodeCamp's <code class='inl'>[1, 2, 3, 10, 2, 1, 0]</code> is exactly 10 and answers <b>true</b>; write <code class='inl'>&gt;</code> and that one case, alone of the seven, goes wrong. The second is <b>"in a row"</b>, a quantifier disguised as a preposition: it means a sliding window of width 3, so there are <b>five</b> windows on a seven-day week rather than the 35 ways of choosing any three days. Read every range word — "any", "single", "in a row", "the seven days" — as an instruction about loop bounds, because that is all they ever are. The one trick worth carrying away is the rewrite: "<b>average ≥ k over m items</b>" is "<b>sum ≥ k·m</b>". An average of 8 over 3 days is a sum of <b>24</b>; an average of 6 over 7 days is <b>42</b>. Do that and every comparison is between two integers, so the boundary behaves and no float has to be trusted at the exact point where the answer flips — which is not hypothetical, since <code class='inl'>[5, 6, 6, 6, 6, 6, 6]</code> totals 41 and <code class='inl'>[3, 9, 4, 8, 5, 7, 6]</code> totals 42, and that single hour is the entire difference between the two answers. Last, short-circuiting is not an optimisation here but the natural shape: the bullets are an <b>OR</b>, so the first true one <i>is</i> the answer. Writing them as a chain of early returns instead of one boolean expression is what lets you check the code against the statement line by line — and it makes plain that the three rules are genuinely independent, since a week like <code class='inl'>[1, 1, 8, 8, 8, 1, 1]</code> trips only the middle one, with no tall day and a 28-hour total.` },
  "missing":         { pattern: "Hashing", spot: `Two clauses in the statement are doing all the work, and both are easy to skim past. The first is the parenthetical <b>"where n is the largest number in the given array"</b> — <code class='inl'>n</code> is the <b>maximum</b>, not the length, and the two agree on every contiguous array, which is exactly why the misreading survives freeCodeCamp's opening cases and then dies on <code class='inl'>[1, 10]</code>: two elements whose answer is <b>eight</b> numbers long. The array is a <i>sample</i> of 1…n, not a measurement of it. The second is the bullet that says the input <b>"may be unsorted and may contain duplicates"</b>. When a spec goes out of its way to <i>disclaim</i> structure, it is not warning you about an edge case — it is telling you the input is a <b>set in disguise</b>, and the first move is to make it one. Once you do, everything downstream stops caring: <code class='inl'>[10,1,10,1,10,1]</code> and <code class='inl'>[1, 10]</code> collapse to the same two members and must therefore return the same answer. That is the Hashing tell here rather than a sorting one — the question "which of 1…n are absent" is <b>"have I seen this?"</b> asked n times, and membership is O(1) while <i>counting</i> occurrences answers a strictly harder question than the one asked. The structural insight is that the <b>search space (1…n) and the data (the array) are different collections</b>, and it is the search space you iterate. Walk the data instead and you end up sorting it, diffing neighbours and hunting gaps — correct, but much fussier, with an off-by-one at each end. Walking <code class='inl'>k</code> upward also hands you the last two rules for free: <b>ascending order</b> is a consequence of the iteration, not a step (and a reflexive <code class='inl'>.sort()</code> would be <b>#309 Number Sort</b> all over again, putting <code class='inl'>11</code> before <code class='inl'>2</code>), while <b>"return an empty array if none are missing"</b> is what a loop that never pushes already leaves behind.` },
  "wordfreq":        { pattern: "Hashing", spot: `<b>"Three most frequently occurring"</b> is a <b>tally</b>, and the giveaway is that the answer depends on <i>counts</i> rather than <i>positions</i> — nothing about where a word sits in the paragraph survives into the output. That is the signal to stop treating the input as a sequence and collapse it into a word→count map in one pass; everything after that is ranking. Read the normalisation literally while you are there: the statement <b>enumerates</b> its punctuation — commas, periods, exclamation points — so a broad <code class='inl'>/[^\\w\\s]/g</code> would strip apostrophes and hyphens nobody asked about. The spec gives a list, and the list <i>is</i> the spec; do it once at the boundary alongside the lowercasing and every later line gets to assume clean input. The transferable half is the <b>tie</b>. Whenever you sort by a <b>derived key that can collide</b> — a count, a score, a length — your comparator is a <i>partial</i> order, and everything it leaves undecided is settled by two things you never wrote down: your sort's <b>stability</b> and the order you built the collection in. <code class='inl'>(a, b) =&gt; b[1] - a[1]</code> returns <b>0</b> for equal counts, which is exactly the region where nothing in your code is choosing. Most statements never say what should happen on a tie, so the <b>test suite quietly encodes an answer</b> — and here it encodes <b>first appearance</b>. freeCodeCamp's own <code class='inl'>"I like coding. I like testing. I love debugging!"</code> counts <code class='inl'>i</code> 3 and <code class='inl'>like</code> 2, then <code class='inl'>coding</code>, <code class='inl'>testing</code>, <code class='inl'>love</code> and <code class='inl'>debugging</code> <b>all tied at 1</b>, and the expected answer is <code class='inl'>["i", "like", "coding"]</code>: <code class='inl'>coding</code> takes the last slot only because it was seen first. That falls out for free from <code class='inl'>Map</code> iterating in <b>insertion order</b> plus <code class='inl'>Array.prototype.sort</code> having been <b>required to be stable since ES2019</b>. Be precise about how much the grader actually proves, though, because it is less than it looks — <b>the official set is blind to stability twice over</b>. Its first case tops out at 4, 3 and 2, so no tie reaches the cut and every sorting algorithm returns the same array; its other two <i>do</i> depend on stability — the third ranks <code class='inl'>debug</code> 4 ahead of <code class='inl'>test</code> 4, and an unstable sort returning <code class='inl'>["test", "debug", "deploy"]</code> fails <code class='inl'>deepEqual</code> — but they tally only 6 and 3 entries, far inside the <i>stable</i> insertion-sort fall-back that V8's pre-TimSort QuickSort used on short arrays (TimSort landed in V8 v7.0 / Chrome 70). So <b>the correctness of this solution rests on a guarantee no official test can check</b>, and that conclusion survives wherever you put the engine's exact boundary. Make the habit explicit: <b>when your comparator can return 0, go and find out what the expected output does with ties before assuming it does not matter</b> — and never read a green test run as proof you got the tie-break right. One more reason the container is a <code class='inl'>Map</code> and not a <code class='inl'>{}</code>: a plain object mostly works here, but it coerces keys and <b>re-orders integer-like keys ahead of everything else</b>, so a word like <code class='inl'>"7"</code> would jump to the front of the iteration order and win a tie it should have lost — another real bug no official test would catch. And <code class='inl'>slice(0, 3)</code> quietly covers what the statement leaves unspecified: with fewer than three distinct words it returns what there is.` },
  "thermostat":      { pattern: "Direct", spot: `The tell is that the statement <b>enumerates its own output space</b> — "return heat / cool / hold" — and gives exactly one condition for each. Three named outputs with three conditions is a <b>lookup table</b>, not an algorithm: there is no state to carry, nothing to search, and no input whose answer is not already written down. That is the <code class='inl'>Direct</code> signal in its purest form, and the skill is recognising it in two seconds and then <i>stopping</i>, because the only way to get this wrong is to build something. What is left generalises to every conditional you write. First, a <b>trichotomy</b> over two numbers is exhaustive — below, above, or equal, with nothing left over — so the final case is a <b>fallthrough</b> rather than a fourth test: <code class='inl'>if (temp === target)</code> adds a branch that cannot fail and invites an <code class='inl'>else</code> that can never run. The one input that reaches the fallthrough <i>without</i> being equal is <code class='inl'>NaN</code>, which makes all three comparisons false — which is why a catch-all belongs last rather than first. Second, the <b>direction</b> of a comparison stated in prose is the single most common place this class of problem is written backwards, because the <i>action</i> is the opposite of the <i>state</i>: "heat" is what you do when the room is <b>colder</b>, so the branch returning it is the one where <code class='inl'>temp</code> is the <b>smaller</b> number. Negative values are the cheapest possible check on that, which is exactly why freeCodeCamp ships <code class='inl'>(-20.5, -10.1)</code> → <code class='inl'>"heat"</code>: −20.5 is the colder temperature despite the larger magnitude, so a solution that reasons about size instead of position passes every positive case and dies on that one. Third, and worth carrying to every <code class='inl'>===</code> you write on a number: exact equality on floating point is safe precisely when the values were <b>given</b>, and unsafe the moment one of them came out of <b>arithmetic</b>. <code class='inl'>72 === 72</code> and <code class='inl'>0.0 === 0.0</code> hold because the caller handed both in, and the official <code class='inl'>(100, 99.9)</code> → <code class='inl'>"cool"</code> is a 0.1 gap that stays decisive for the same reason. Compute one side — <code class='inl'>0.1 + 0.2</code> against <code class='inl'>0.3</code> — and the equal branch is not merely unlikely, it is <b>unreachable</b>.` },
  "capitalize":      { pattern: "Simulation", spot: `The tell is that the rule for any one character depends on <b>what came before it</b>, not on the character itself. "Capitalise this letter if a sentence just ended" is a statement about <i>history</i>, and history means state — so the shape of the answer is one left-to-right pass carrying one boolean, not a clever expression over the whole string. The signal generalises: whenever a transformation is described in terms of <b>positions relative to delimiters</b>, and those delimiters can repeat (<code class='inl'>!!!</code>), cluster, or be separated from their target by arbitrary filler (<code class='inl'>". "</code>, or even <code class='inl'>" . "</code>), a single scan carrying one flag beats any amount of splitting and rejoining — because splitting throws away exactly the thing you are required to preserve, the delimiters and the spacing between them, and then you have to put it all back. freeCodeCamp's own set proves it, and the way it proves it is the interesting part. The two shortcuts people reach for fail on <b>disjoint</b> cases. <code class='inl'>split(". ")</code> passes four of the five and fails only <code class='inl'>"crazy!!!strange???unconventional...sentences."</code>, which has no whitespace anywhere, so the whole paragraph comes back as a single piece. "Capitalise the character after an ender" passes that one and fails the other three, because after the ender in <code class='inl'>"there's a space before this period . why …"</code> comes a space, and <code class='inl'>" ".toUpperCase()</code> is a space. Neither is a near miss, and — this is the point — neither one's blind spot is covered by the other's strength in a way you can compose: bolt them together and you are writing the flag by hand, badly. Then the part worth carrying away: in a state machine the hard question is never <b>when do I set the flag</b> — the enders are right there in the statement — it is <b>what leaves the flag alone</b>. There are three categories here, not two: <code class='inl'>/[.?!]/</code> arm it, letters and digits clear it, and spaces, apostrophes and quotes must do neither. That third one is invisible until it bites. An apostrophe sits <i>inside</i> a word, so a machine that re-arms on "any punctuation" turns <code class='inl'>today's</code> into <code class='inl'>today'S</code>; one that clears on "any non-letter" drops the flag on the space in <code class='inl'>". "</code> and capitalises nothing at all. Enumerate the characters that must <i>not</i> touch your flag before you write the ones that do — that is where the bugs live.` },
  "slug":            { pattern: "Direct", spot: `The statement is a <b>numbered list of transformations</b> — lowercase, remove, replace, collapse, trim — with nothing to search and no condition to test. That shape has a name: it is a <b>pipeline</b>, which means the algorithm is already written for you and the only engineering left is the <b>order</b>. The rule is to pick the order in which each rule is <i>simplest to state</i>, and that almost always means destructive normalisation first and <b>representation changes last</b> — encoding, escaping and formatting are the operations that change the alphabet every later rule has to be written against. Here the payoff is exact. "Consecutive spaces become a single <code class='inl'>%20</code>" and "no leading or trailing <code class='inl'>%20</code>" <i>sound</i> like rules about <code class='inl'>%20</code>, but they are rules about <b>whitespace</b>: while whitespace still exists they are <code class='inl'>.split(/\\s+/)</code> and <code class='inl'>.trim()</code>, one token each, with the collapse falling out of the <code class='inl'>+</code> for free. Encode first and both must be restated against a three-character token — <code class='inl'>/(%20)+/</code> and <code class='inl'>/^(%20)+|(%20)+$/</code> — and rules rewritten against an encoded form are where the bugs are. The same ordering keeps two stages off the same character: the official <code class='inl'>"  ?H^3-1*1]0! W[0%R#1]D  "</code> contains a literal <code class='inl'>%</code>, and the strip that deletes it is only safe because no <code class='inl'>%20</code> of ours exists yet. A cheaper win sits at the top — lowercase <b>before</b> the strip, so the pattern is <code class='inl'>[^a-z0-9 ]</code> rather than <code class='inl'>[^a-zA-Z0-9 ]</code>; get that backwards and the short pattern does not complain, it silently deletes every capital. The last tell is not about order at all: <b>a familiar problem name imports assumptions the spec does not share.</b> Every slug library turns punctuation into a hyphen; this statement says non-letters are <b>removed</b>, so <code class='inl'>" hello-world "</code> is <code class='inl'>"helloworld"</code> — the words fuse and no separator survives. Whenever a problem arrives with a name you recognise, run its own stated examples in your head before writing anything; it is the cheapest way to find out you are solving the problem you remember instead of the one on the page.` },
  "filltank":        { pattern: "Gotcha", spot: `The arithmetic is a subtraction and a multiplication, so notice how little of the statement that consumes — and then notice that the statement spends its <b>last bullet</b> on an output format. A spec that pins a currency format to two decimal places is telling you where the entire difficulty is, because the sum was never going to be the hard part. <code class='inl'>toFixed(2)</code> is the right reach: it discharges three separate obligations of <code class='inl'>"$d.dd"</code> in one call — always two decimals (<code class='inl'>"$80.00"</code>, not <code class='inl'>"$80"</code>), always at least one leading digit (<code class='inl'>"$0.00"</code>, not <code class='inl'>"$.00"</code>), and the point itself when the cents are zero — and it returns a <b>string</b>, which is why the <code class='inl'>"$"</code> concatenates and why nothing downstream should do arithmetic on the result. It also means the already-full tank needs no branch: zero gallons times any price is zero, and the formatter does the rest, so an <code class='inl'>if (fuelLevel === tankSize)</code> guard would be code that can never change an answer. The transferable tell is <b>money in floating point</b>. Any spec that fixes a currency format is a spec where the obvious rounding call is correct on the graded inputs and subtly wrong in general, because the value being rounded is a <b>binary approximation</b> and a decimal midpoint ending in 5 is never exactly representable: <code class='inl'>(1.005).toFixed(2)</code> is <b>"1.00"</b>, <code class='inl'>(2.675).toFixed(2)</code> is <b>"2.67"</b>, <code class='inl'>(8.575).toFixed(2)</code> is <b>"8.57"</b>. <code class='inl'>toFixed</code> is not misbehaving — it rounds the number it was handed, and the nearest double to 1.005 is <b>1.0049999999999998934</b>, genuinely below the midpoint. This is not a JavaScript wart either; it is an <b>IEEE-754</b> consequence every language with binary floats shares, and it does not need an exotic input to reach: half a gallon at <b>$4.05</b> is already one. Nor is <code class='inl'>Math.round(x * 100) / 100</code> the escape, and seeing why is worth more than the rule. On that same half-gallon the two disagree by a cent: <code class='inl'>toFixed</code> judges the stored <b>2.0249999999999999112</b>, just below the midpoint, and gives <b>2.02</b> — while <code class='inl'>2.025 * 100</code> is <i>exactly</i> <b>202.5</b>, the multiplication having rounded away the very tail the decision rested on, so <code class='inl'>Math.round</code> applies its own halves-go-up rule and gives <b>2.03</b>. One rounds the true value; the other rounds a value it damaged on the way in. Swapping strategies is not a fix, it is a different failure. The reliable habit, then, is to never let a currency value <i>exist</i> as a float you will later round — carry integer <b>cents</b>, or a decimal type. But read the other half of the tell too: <b>none of freeCodeCamp's five cases lands on a midpoint</b> (the raw products are 80, 17.5, 29.25, 0 and 21.89, every one clean at display precision), the grader cannot catch any of this, and for a daily challenge <code class='inl'>toFixed(2)</code> <b>is</b> the intended answer — reaching for a decimal library is answering a different question than the one on the page. Recognising which of those two problems you are being asked to solve is the actual lesson.` },
  "photos":          { pattern: "Math", spot: `Count the bullets: one pins down a <b>unit conversion</b>, the other says the word <b>whole</b>. Neither describes a data structure, a traversal or a search, and that absence is the signal — when a statement spends itself on units and rounding, the answer is an expression and every bug it can have lives in one of those two places rather than in a loop. Read both bullets as warnings rather than as pedantry. A spec only bothers to state <b>"1 gigabyte equals 1000 megabytes"</b> when the factor is <i>contested</i>, and this one is: drive manufacturers sell decimal GB (10⁹ bytes) while operating systems have historically reported binary GiB (2³⁰ bytes, 1024 MB), which is the whole reason a "1 TB" drive shows up as 931 GB. Take 1024 and <code class='inl'>(4, 256)</code> returns <b>65536</b> instead of <b>64000</b> — a defensible reading of "256 GB" and the wrong answer. The habit worth carrying: <b>a stated conversion factor is always load-bearing</b>, because it is only ever written down to overrule the one you would have assumed. Then <b>"the number of whole X"</b> is a rounding instruction, and it means <code class='inl'>Math.floor</code> — a partial photo is no photo. Write it explicitly rather than trusting the arithmetic to come out integral, because JavaScript has no integer division and no integer type to fall back on; <code class='inl'>(3.5, 750)</code> is the official case built to catch <code class='inl'>Math.round</code>, since <b>214285.71</b> must become <b>214285</b>. Convert the drive <i>down</i> into the photo's unit rather than the photo up — one multiply against one divide, and the larger unit disappears before any division happens. One hazard no official test reaches: <code class='inl'>floor</code> on a float quotient sits one ULP from being wrong, and <code class='inl'>(4.4, 1.1)</code> is exactly <b>250</b> yet computes as <b>249.99999999999997</b> and floors to <b>249</b> — an error too small to print becoming an error of one whole item. Scale both operands to integers before dividing if that has to be right.` },
  "besthand":        { pattern: "Direct", spot: `No search, no math trick — reduce five cards to a <code class='inl'>groups</code> shape plus flush/straight flags, then a strongest-first cascade of <code class='inl'>if</code>s. A <b>fixed classification</b> is straight implementation.` },
  "parens":          { pattern: "Recursion", spot: `<b>n pairs of parentheses</b> is a self-similar structure — every valid string is a smaller valid one with a balanced pair added. A nested, self-referential shape means solve it by recursion.` },
  "schema":          { pattern: "Recursion", spot: `The schema <b>nests</b> — objects hold fields, arrays hold elements, each itself a schema. When the data is a tree of the same shape, validate it with a function that calls itself on each child.` },
  "itinerary":       { pattern: "Math", spot: `It asks <b>how many</b> arrangements exist, not to list them. A fixed skeleton with counted gap-placements collapses to <code class='inl'>(2n−3)·n!</code> — reach for a closed-form formula, not enumeration.` },
  "luhn":            { pattern: "Direct", spot: `The spec <i>is</i> the algorithm: double every other digit, cast down by 9, sum, test <code class='inl'>% 10</code>. Translate the stated checksum steps straight into one pass — no pattern to discover.` },
  "sort":            { pattern: "Gotcha", spot: `The one-line <code class='inl'>.sort()</code> looks correct. Whenever a built-in has a <b>default behaviour</b> (JS sorts as text, so <code class='inl'>"12"</code> lands before <code class='inl'>"2"</code>), suspect it on numbers — that surprise is the whole problem.` },
  "prime":           { pattern: "Math", spot: `"Prime factors, with multiplicity" is a <b>divisibility</b> question — trial-divide, and crucially stop at <code class='inl'>√n</code>. The factor structure and the √n cutoff are arithmetic, not brute enumeration.` },
  "dna":             { pattern: "Direct", spot: `"Equal-length strands, return the indexes where they differ" is a single <b>positional scan</b> collecting mismatches. The equal-length promise tells you it's a straight base-by-base compare — no alignment cleverness.` },
  "blood":           { pattern: "Greedy", spot: `Scarce supply, and serving order changes how many you help — the signal to serve the <b>most-constrained patient first</b> (O-only before flexible AB). Committing to the locally-hardest case first is the greedy win.` },
  "periodic":        { pattern: "Backtracking", spot: `Spell a word from element symbols where each letter starts a <b>1- or 2-letter</b> symbol — try one, recurse, and <b>undo</b> on a dead end. Branching choices you can unwind is backtracking.` },
  "connect3":        { pattern: "Direct", spot: `Scan every cell in four directions for three in a row — a straight <b>grid scan</b> with fixed checks. Recognising there's no clever pattern (just enumerate the lines) stops you over-engineering.` },
  "mood":            { pattern: "Direct", spot: `A genre plus a BPM into a mood via inclusive ranges — a plain <b>lookup + range check</b>. Translate the stated bands directly; there's no algorithm hiding behind the table.` },
  "dupcount":        { pattern: "Hashing", spot: `"How many chars of str2 appear in str1" — you keep asking <b>"is this char present?"</b> Build a set of str1's chars once for O(1) membership instead of rescanning str1 each time.` },
  "lucky":           { pattern: "Direct", spot: `A wordy arithmetic recipe — count vowels/consonants, multiply the mins, multiply the maxes, subtract. Just <b>translate the formula</b> as written; the density is bookkeeping, not a hidden pattern.` },
  "profit":          { pattern: "Dynamic programming", spot: `You want the best over all buy/sell pairs, but each buy day only needs the <b>best price still ahead of it</b> — when a later choice depends on a running aggregate, carry it in one pass instead of re-scanning.` },
  "migrate":         { pattern: "Direct", spot: `"Fill missing schema fields, never overwrite existing ones" is a single <b>merge scan</b> over the schema keys with an <code class='inl'>in</code> check. Straight implementation — spot that and skip any framework instinct.` },
  "kaprekar":        { pattern: "Simulation", spot: `"Count how many steps to reach 6174" — the problem hands you one step and a stop condition. Just <b>run the process</b> (sort digits, subtract, repeat), tallying iterations.` },
  "bucketfill":      { pattern: "Flood fill", spot: `Replace a start cell and every <b>4-connected</b> neighbour sharing its value — a connected region on a grid. "Spread from a seed to like-valued neighbours" is the flood-fill signal.` },
  "lowerwords":      { pattern: "Direct", spot: `"Keep words that are entirely lowercase" — the rule is literally <code class='inl'>word === word.toLowerCase()</code>. Split, <b>filter</b> on that predicate, rejoin. A one-line filter, no pattern needed.` },
  "nearmult":        { pattern: "Math", spot: `"Round to the nearest multiple of n" is pure arithmetic — <code class='inl'>Math.round(a/b)*b</code>. The "nearest multiple of" phrasing points at a formula, not a loop over candidates.` },
  "triage":          { pattern: "Direct", spot: `Fixed rules on a day-count and a substring check — just translate the thresholds into <b>conditionals</b>. No search or optimization; recognising there's no trick saves you the time.` },
  "triage2":         { pattern: "Direct", spot: `A branching set of label rules (seed when empty, else first-matching triage, then append critical) — a <b>chain of conditionals</b> applied in order. Follow the spec's if/else ladder literally.` },
  "exactchange":     { pattern: "Dynamic programming", spot: `"Count the <b>distinct</b> ways to make change", order-independent with reusable coins — count-the-ways with overlapping subproblems. Fold each coin into a <code class='inl'>ways[]</code> table so you never recompute.` },
  "horoscope":       { pattern: "Math", spot: `The signs form a <b>wheel</b> — "wrapping back to Aries after Pisces" is the giveaway. Once a structure is <b>circular</b>, positions are arithmetic mod 12 and the distance folds: <code class='inl'>Math.min(gap, 12 - gap)</code>. Reach for the modular formula, not a walk around the ring.` },
  "fivedice":        { pattern: "Direct", spot: `Map five dice to the best-ranked hand — tally duplicates, check for runs, then a strongest-first <b>classification cascade</b>. A fixed rank table is direct implementation, not a search.` },
  "tally":           { pattern: "Direct", spot: `The problem hands you a <b>notation</b> and dares you to decode it. Read the spec literally: "every fifth mark is a <code class='inl'>/</code>" says the slash <b>is</b> the fifth mark, not that it's worth five. Once every symbol counts as one, the separator is the only character that isn't data — each group's <code class='inl'>.length</code> already is its count.` },
  "pet-age":         { pattern: "Direct", spot: `The problem <b>prints you a table</b> and asks for one row times one number. When the spec is already a key→value mapping, transcribe it as data and the whole solution is <code class='inl'>TABLE[key] * n</code>. Reach for a chain of <code class='inl'>if</code>s and you've re-encoded the table as control flow for nothing.` },
  "chunks":          { pattern: "Direct", spot: `The output is the <b>same elements in the same order</b> — only the grouping changes, and it's decided by arithmetic on the index, not by anything in the data. That means a stride loop: <code class='inl'>i += size</code>, not <code class='inl'>i++</code>. And when you catch yourself special-casing the ragged tail, stop — <code class='inl'>slice</code> already clamps, so the short last chunk is free.` },
  "pig-latin":       { pattern: "Direct", spot: `Three rules, no search: split on spaces and rewrite each word independently. But read rule 3 twice — "preserve the case of the first letter" is not "keep the capital", because the letter that <i>was</i> first has just moved to the back. When a transform relocates the front of a token, anything attached to <b>position</b> must be re-derived after the move, not carried along with the character.` },
  "birthday":        { pattern: "Math", spot: `The answer is a <b>distance</b> between two dates, and the second one has <b>no year</b> — so the real question is "which year does it belong to?". That's construct-and-subtract, not traversal. The tell that you're being tested on arithmetic rather than iteration is the <b>2/29</b> case, whose spacing is governed by the /4, /100, /400 rule.` },
  "elevator":        { pattern: "Greedy", spot: `Two clauses do all the work, and one of them isn't about cost at all: <b>"must be visited when the elevator first passes them"</b> forbids doubling back, which means the car sweeps one way, turns <b>once</b>, and sweeps back. That collapses <code class='inl'>k!</code> orderings to <b>two</b>. Once a constraint has reduced the choice to a handful, stop searching and start comparing — commit to the nearer turnaround, because the leg you take first is the one you pay for twice.` },
  "golden":          { pattern: "Math", spot: `<b>"Approximates"</b> is the whole spec: never <code class='inl'>===</code>, always <code class='inl'>|value − target| &lt;= epsilon</code>. And when a problem says "their ratio" without naming an order, the arguments can arrive either way round — normalise with <code class='inl'>max / min</code> up front rather than handling two cases downstream.` },
  "blender":         { pattern: "Direct", spot: `Two rules that look like mirror images — take the <i>shorter</i> front half, take the <i>longer</i> back half — and the tell is that they're the same index seen from opposite sides. Before writing <code class='inl'>floor</code> for one and <code class='inl'>ceil</code> for the other, check whether <b>one operator used as an end bound and then as a start bound</b> already expresses both. It does, and the parity branch disappears.` },
  "piggy":           { pattern: "Direct", spot: `Money: count in the <b>smallest unit</b> and let the decimal point be a formatting step, so no rounding decision ever enters the arithmetic. The other tell is in the phrase "may contain any of the following" — keys can be <b>absent</b>, not merely zero, so every lookup needs a default or the first miss turns the whole sum into <code class='inl'>NaN</code>.` },
  "gametheory":      { pattern: "Direct", spot: `A small rule set indexed by a <b>combination</b> of inputs. Rather than testing the combination with conditionals, <b>build the key out of the inputs</b> — <code class='inl'>p1[i] + p2[i]</code> already spells "CC", "CD", "DC" or "DD" — and let a table hold the rules. A 2×2 grid re-encoded as control flow is longer and impossible to check against the spec at a glance.` },
  "loan":            { pattern: "Simulation", spot: `The question asks for <b>every intermediate value</b>, not a final one, so there is nothing to close-form — just run the months. The trap is where the rounding lives: "return each balance rounded" describes the <b>output</b>, so round what you push and carry the exact figure, or next month's interest is charged on a number nobody owes. Whenever a spec rounds <i>results</i>, keep the state at full precision.` },
  "cellsignal":      { pattern: "Math", spot: `A measurement that is <b>exact and directional</b> — "n cells away in a straight line" — doesn't narrow the grid, it <b>names</b> eight cells. That's the flip worth spotting: when a constraint <i>determines</i> a small candidate set rather than merely testing one, generate the set and verify it, instead of enumerating the space and filtering. Alignment is <code class='inl'>dr === 0 || dc === 0 || |dr| === |dc|</code> and the distance along a ray is just <code class='inl'>Math.max(|dr|, |dc|)</code>.` },
  "dice-odds":       { pattern: "Dynamic programming", spot: `It asks <b>how many</b> combinations hit a target, not <b>which</b> ones — and the space is exponential (<code class='inl'>6^dice</code>). When you need only a <i>count</i> over an additive target, carry counts forward instead of enumerating: the ways to reach sum <code class='inl'>s</code> with <code class='inl'>d</code> dice depend only on the ways to reach <code class='inl'>s−1 … s−6</code> with <code class='inl'>d−1</code>. One row per die replaces the whole tree.` },
  "letterdist":      { pattern: "Math", spot: `Two equal-length strings and a per-position sum — but the whole problem hides in the aside: <b>&quot;the alphabet is treated as a circle, so a and z are 1 apart&quot;</b>. The moment a structure <b>wraps</b>, <code class='inl'>Math.abs(a - b)</code> is only one of the two answers; the ways round always sum to 26, so the distance is <code class='inl'>Math.min(gap, 26 - gap)</code> — which also <i>proves</i> no pair can exceed 13. The equal-length promise is the second tell: one index walks both strings, so there is no alignment to work out, only n independent folds to add up.` },
  "pronic":          { pattern: "Math", spot: `"The product of two <b>consecutive</b> integers" names an equation, not a search space: <code class='inl'>k² + k − n = 0</code> has a single non-negative root, so at most <b>one</b> k can possibly work. And because <code class='inl'>k² ≤ k(k+1) &lt; (k+1)²</code>, that k is pinned to <code class='inl'>Math.floor(Math.sqrt(n))</code> — multiply it out once and you are done. The tell is that the candidates are <b>strictly increasing</b>: the moment k·(k+1) passes n, looping further can only overshoot, which means the loop was never needed. Watch the degenerate end too — 0 = 0 × 1 is pronic, so k starts at <b>0</b>.` },
  "contrast":        { pattern: "Direct", spot: `The spec <b>prints you a 2×3 grid</b>, and the job is reading it in the right direction. Down the rows it is <b>ordered</b>, so the answer is the <b>first</b> threshold the ratio clears — an early return from an ordered table already <i>is</i> the priority logic. Across the columns only the number changes, so <code class='inl'>isLargeText</code> should pick a <b>column</b> of one row, <code class='inl'>[rating, normalMin, largeMin]</code>, not fork the code and let the two halves drift. Then read the boundary words literally: <b>"7.0+"</b> is inclusive, so <code class='inl'>&gt;=</code> — and <b>"below 4.5"</b> is that row's exact complement, which means <code class='inl'>"Fail"</code> is not a threshold at all, just what is left when nothing was cleared.` },
  "contrast2":       { pattern: "Math", spot: `Two values whose <b>zero is real</b> — black's relative luminance genuinely <i>is</i> 0 — and the spec asks you to divide by one of them. That is the tell for a <b>guard constant</b>: the <code class='inl'>+0.05</code> added to <i>both</i> sides isn't a fudge factor to tune away, it is what makes the quotient defined at all, and it pins the whole scale to <code class='inl'>1 … 21</code>. The other half is taking "divide the lighter by the darker" literally — a <b>ratio</b> and a <b>difference</b> rank the same pair differently, and the spec chose the one that matches how contrast is perceived.` },
  "contrast3":       { pattern: "Direct", spot: `Every constant in the statement is <b>load-bearing</b> — that is the tell. When a spec bothers to name <code class='inl'>0.04045</code>, <code class='inl'>12.92</code> and <code class='inl'>** 2.4</code>, it is telling you the number you were handed is <b>not</b> the quantity you need: a channel's 0–255 is a storage code, and the curve is what turns it into light. So the instinct to tidy the recipe up — average the channels, skip the exponent — is the trap, not the shortcut; it silently drops <code class='inl'>[215,188,188]</code> on <code class='inl'>[55,55,55]</code> from <b>AA</b> to <b>Fail</b>. Transcribe it exactly, weights and all (<code class='inl'>0.7152</code> for green against <code class='inl'>0.0722</code> for blue is the eye, not a normalisation), because there is no algorithm hiding underneath the arithmetic.` },
  "morse":           { pattern: "Direct", spot: `The problem hands you a <b>notation</b> and dares you to decode it — but the load-bearing part of the spec isn't the alphabet, it's the two lines underneath it. <code class='inl'>"."</code> is E, <code class='inl'>".."</code> is I, <code class='inl'>"..."</code> is S, so nothing in the dots and dashes says where a letter ends; only the <b>width of a gap</b> does. When a format uses the <i>same character</i> at two sizes as two different delimiters, split on the <b>wider</b> one first — <code class='inl'>split("&nbsp;&nbsp;&nbsp;")</code> into words, then <code class='inl'>split(" ")</code> inside each — because the narrow split can't see a gap it has already destroyed, and leaves you counting empty strings to get it back.` },
  "magicsquare":     { pattern: "Math", spot: `You are handed <b>eight of the nine</b> numbers plus a definition, which means the missing one is already <b>determined</b> — there is nothing to search for. The tell is that the hole sits in exactly <b>one</b> row, so another row is complete, and a complete line <i>is</i> the magic constant: the answer is <code class='inl'>S − (the two knowns in the hole's row)</code>, one subtraction. The other half of the problem is the half most solutions miss — a deduced value is not a proof, so fill it in and check all <b>eight</b> lines (both diagonals) before returning it, because <code class='inl'>"impossible"</code> is a real answer.` },
  "foodchain":       { pattern: "Hashing", spot: `The apex is defined by an <b>absence</b> — "never prey to another animal" — and an absence is the one thing you cannot confirm without reading the <i>whole</i> list. That's the tell: rather than scanning for what <b>isn't</b> there, spend one pass collecting what <b>is</b>, and the apex falls out as the single name missing from a <code class='inl'>prey</code> Set. The second tell is that the pairs arrive in <b>no guaranteed order</b>, so every link means another hunt through them — the cue to write <code class='inl'>predator → prey</code> down in a Map once and turn each hop into a lookup.` },
  "emoji":           { pattern: "Gotcha", spot: `The printed table is the decoy — transcribe it and you feel done, and then <code class='inl'>str.split("")</code> quietly hands the lookup <b>half an emoji</b>. The tell is that the data is <b>non-ASCII</b>: <code class='inl'>.length</code>, <code class='inl'>str[i]</code> and <code class='inl'>split("")</code> all count <b>UTF-16 code units</b>, while <code class='inl'>[...str]</code>, <code class='inl'>Array.from</code> and <code class='inl'>for…of</code> count <b>code points</b> — and anything above <code class='inl'>U+FFFF</code> costs two units. What makes it worth spotting rather than debugging is that the alphabet is <b>mixed</b>: ⭐ is one unit and the other nine emoji are two, so a test built from stars passes either way and tells you nothing.` },
  "handicap":        { pattern: "Direct", spot: `Two arrays that only mean anything <b>in lockstep</b>, plus a one-sentence recipe: subtract, average, round. Translate it literally — the density is bookkeeping, not a hidden pattern. The clause worth slowing down on is the last one. <b>"Rounded to one decimal place"</b> describes the <i>return value</i>, so round once at the end and hand back a <b>number</b>: <code class='inl'>toFixed(1)</code> returns a string and fails a <code class='inl'>===</code> grader on every case, including the ones where nothing gets rounded. And a round under par gives a <b>negative</b> differential — so prefer <code class='inl'>Number(x.toFixed(1))</code>, which rounds the value half <i>away from zero</i>, over <code class='inl'>Math.round(x * 10) / 10</code>, which rounds a scaled copy and breaks ties toward +∞, turning −2.25 into −2.2.` },
  "duration":        { pattern: "Direct", spot: `Three units and a punctuation rule, no search — but the spec's own <b>order</b> is the tell: <i>skip any zero values</i> is stated <b>before</b> <i>join the last two with "and"</i>. Obey that order and you no longer know how many pieces you are holding, so a comma attached to a <b>unit</b> ("one goes after the hours") prints <code class='inl'>"1 hour, and 1 second"</code> the moment the minutes are zero. Whenever a <b>filter runs before a format</b>, the format has to read the surviving list's <code class='inl'>.length</code> rather than the original slots — and then one expression covers both the three-part and the two-part case, because <code class='inl'>parts.slice(0, -1).join(", ")</code> has no gap to put a comma in when only one item is left.` },
  "spokentime":      { pattern: "Math", spot: `The inputs are <b>continuous</b> and the answer is <b>discrete</b>, so the whole problem is a unit conversion plus one quantising choice — and the spec only waves at it: <i>"consider rounding them somehow"</i>. Don't reflex to <code class='inl'>Math.round</code>; ask what the instrument <b>means</b>. A clock hand has already swept <b>past</b> the mark it names, so both hands take <code class='inl'>Math.floor</code> — rounding turns 8.5 hours into 9 and 45.5 minutes into 46, losing <code class='inl'>"half past 8"</code> and <code class='inl'>"quarter to"</code> outright. The second tell is the <b>Y/Z</b> pair: "the current hour" and "the next hour" on a fixed-size cycle is <code class='inl'>(i + 1) % n</code> with a display fix-up, never a special case.` },
  "nonogram":        { pattern: "Direct", spot: `The clue reads like an invitation to search — try every placement of a 3 then a 2 and see if one fits the row. But you are handed the <b>finished</b> row, so read it instead of solving it. The tell is the phrase "separated by at least one empty cell": that is a fact about the data, not a condition you have to test, so <code class='inl'>cells.join("").split("0")</code> enforces it for free — the separators are already in the input. What is left is comparing two arrays, and it must be <b>element-wise</b>: a sum or a set would happily accept runs of <code class='inl'>[2, 3]</code> for a clue of <code class='inl'>[3, 2]</code>.` },
  "bucketfill2":     { pattern: "Flood fill", spot: `The question asks <b>how many operations</b>, not for the repainted grid — and each operation acts on a whole <b>region</b>, never a cell. That mismatch is the clue: run the flood fill of <b>#329</b> not to recolour anything but to <b>label connected components</b>, and the grid stops being a grid. It is a handful of nodes, and the answer is a property of the node set. The trap is counting <b>colours</b> — two "G" blobs that never touch are two nodes and two clicks, so group by <i>connectivity</i>, not by value. Then notice what the fixed target colour buys you: a wrong-coloured region can never be repainted into its neighbour, so it can never grow or merge, and one click clears all of it. No ordering to search, no state space — just <b>count the nodes that are the wrong colour</b>.` },
  "mixpaint":        { pattern: "Math", spot: `Two things arrive carrying the values you want to blend, and a <i>second</i> pair of numbers that says how much each one counts — that is the shape of a <b>weighted average</b>, <code class='inl'>(a·wa + b·wb) / (wa + wb)</code>, not a midpoint and not a loop over candidates. The giveaway that the weights are real is that they are allowed to differ: equal fullness is the only input where <code class='inl'>(a + b) / 2</code> would have passed. The second tell is <b>where the spec puts the rounding</b> — "each channel rounded to the nearest integer" means <code class='inl'>Math.round</code> lands <b>after</b> the divide and <b>inside</b> the per-channel loop, so one call can legitimately round R down and G up.` },
  "bucketfill3":     { pattern: "Flood fill", spot: `Two clauses do the damage, and neither is the flood fill. "Return the <b>minimum</b> number of clicks" makes it an optimisation, and "clicks can use <b>any</b> colour as an intermediate step" leaves the colour of every single click unconstrained. Together they mean no local rule can pick the next move — a colour you do not want anywhere in the answer can still be the cheapest way to glue two patches together first, and nothing in the current board tells you that. When a problem hands you a <b>free choice on every move</b> and asks for the <i>shortest sequence</i>, stop hunting for a formula and start bounding a search. The next thing to look for is an <b>admissible floor</b> to deepen against, so most branches die untried: here a click paints one blob one colour, so it can retire at most <b>one colour</b> from the board — any position needing more colours retired than it has clicks left is hopeless before you generate a single move.` },
  "vowelbal":        { pattern: "Direct", spot: `Three rules and no algorithm — the only difficulty is transcribing them without inventing a fourth. Two of them cost nothing: <b>"in either uppercase or lowercase"</b> is one <code class='inl'>/i</code>, and <b>"can contain any characters"</b> needs no branch at all, because a digit or a symbol simply fails the vowel test like every other non-vowel. The third is the whole problem. <b>"If there's an odd number of characters, ignore the center character"</b> is not an extra step to code — it is a statement about <i>where the second half starts</i>, so write the two bounds as a pair that disagree by one, <code class='inl'>slice(0, Math.floor(n / 2))</code> and <code class='inl'>slice(Math.ceil(n / 2))</code>, and the parity branch disappears. What makes it worth spotting rather than debugging is that getting it wrong is <b>invisible on half the tests</b>: on an even length floor and ceil are the same number, so an off-by-one here passes every even case, and among the odd ones it only changes the answer when the ignored centre happens to be a vowel itself.` },
  "basecheck":       { pattern: "Direct", spot: `Base 2 allows 0–1, base 8 allows 0–7, base 16 adds A–F, base 36 adds A–Z — the prompt hands you the rule as a table of ranges, but they are one list cut at different points. Give each character its <b>value</b> (its index in <code class='inl'>0…9A…Z</code>) and the whole table collapses to <code class='inl'>value &lt; base</code>, with <code class='inl'>−1</code> for "not a digit at all". When a stated table restates as one comparison, that is straight implementation — and it is also why <code class='inl'>parseInt</code> is not the answer: it stops at the first illegal character instead of rejecting the string.` },
  "fibseq":          { pattern: "Dynamic programming", spot: `Each term is defined by a <b>fixed, backward-looking window</b> — the two immediately before it, never anything ahead — and that is the entire licence for a single forward pass: fill position <code class='inl'>i</code> once and it is never revisited, so a recursive <code class='inl'>fib(i)</code> would only be recomputing numbers already sitting in the array. Here the table <b>is</b> the return value, which is why the memo question never comes up. The problem-specific twist is that the base case is not a constant — it is an <b>argument</b>. You are handed the first two numbers, so the table arrives <i>pre-seeded</i> and there is no <code class='inl'>if (n &lt; 2) return n</code> to write; the difficulty migrates out of the recurrence and into the <b>copy</b>. That is where to read the spec twice: <code class='inl'>length</code> counts <b>everything</b>, seeds included, so at length 1 the correct answer is <b>shorter than the input you were given</b>. Whenever a problem hands you the base case as data, ask what it means to request <i>less</i> of it than it supplied — <code class='inl'>startSequence.slice(0, length)</code> clamps at both ends and settles 0, 1 and 2 in one call, while the instinctive <code class='inl'>[...startSequence]</code> has already overshot two of the five official tests before the loop is reached.` },
  "spacejam":        { pattern: "Direct", spot: `Three edits are listed — remove the spaces, insert two spaces between every character, uppercase the letters — and the tell is that the list is <b>not</b> a pipeline. One stage <b>deletes</b> the exact character another stage <b>inserts</b>, so their order is load-bearing in a way the statement never mentions. Strip <i>last</i> and <code class='inl'>replaceAll(" ", "")</code> cannot tell your separators from the input's — it wipes every gap you just added and returns one solid word. Skip the strip and the input's own spaces are still <b>characters in the list</b>, so each one gets padded like any other and a single gap comes back as <b>five</b> spaces. Whenever a cleanup step and the output share a character, the cleanup has to run <b>first</b>. Then read <b>"between"</b> literally: <code class='inl'>join</code> puts a separator between items, not after each one, so <code class='inl'>n</code> characters give <code class='inl'>n − 1</code> gaps — <code class='inl'>"X"</code> comes back bare, and none of the five official assertions covers that.` },
  "jbelmu":          { pattern: "Direct", spot: `The title <b>is</b> the spec — "Jbelmud" is "jumbled" with its middle sorted, and spotting that hands you the whole rule before you read it. Then two clauses quietly decide the code for you. First, <b>the promise is load-bearing</b>: "entirely lowercase" and "no punctuation" mean every element you sort is a <i>single lowercase character</i>, and for those the default comparator&#39;s text order <b>is</b> alphabetical order — so the bare <code class=inl>.sort()</code> that silently ruins numbers in <b>#309</b> is exactly the right call here. The transferable rule was never "always pass a comparator"; it is "know what the default does to <i>your</i> elements", and half the time the answer is that it already does the right thing. Second, <code class=inl>slice(1, -1)</code> <b>clamps</b>, so a 2- or 3-letter word needs no branch coming apart — but it does going back together: on a 1-letter word the "first" and the "last" are the <b>same character</b>, so a reassembly that reads each end independently emits it <b>twice</b> (<code class=inl>"i"</code> → <code class=inl>"ii"</code>). Whenever a transform cuts a token into pieces it then re-joins, find the length at which those pieces stop being <b>disjoint</b> — that boundary, not the empty middle, is where the guard belongs.` },
  "lastload":        { pattern: "Direct", spot: `The function is called <code class='inl'>lastLoadDate</code> and the sentence under it asks for <b>"the number of full days"</b> — two different return types, so read the <b>assertions</b> rather than the name: every one of them compares against an integer, and the answer is a <b>count</b>. After that the recipe is stated outright — average the history, divide — and the only judgement left is the word <b>"full"</b>. A day you can only half-supply is not a day you get, so it is <code class='inl'>Math.floor</code>: 20 scoops at 10.4/day is 1.92 days, and <code class='inl'>Math.round</code> would promise <b>2</b>. Check the <i>other</i> end of that boundary too, because it decides which way an exact division falls — 10 scoops at exactly 2/day is <b>5</b>, so the last load counts <b>in</b>. The tell the grader never reaches is in the spelling: <code class='inl'>scoops / (total / usage.length)</code> divides <b>twice</b>, and the average in the middle is rarely exact in binary, so 35 scoops against <code class='inl'>[3, 2, 2]</code> — exactly 15 days — comes back as <code class='inl'>14.999999999999998</code> and the floor eats a whole day. Whenever a <b>floor follows a division</b>, keep it to one division of two whole numbers: <code class='inl'>scoops * usage.length / total</code>.` },
  "jetlag":          { pattern: "Direct", spot: `The spec prints a table <i>and</i> writes its own formula out as three numbered steps, so the only real decision is how literally to read it — and the answer is <b>completely, including the precedence</b>. <code class='inl'>difference + (flight * 0.1) * multiplier</code> means <code class='inl'>*</code> binds first, so the eastbound <b>1.5</b> scales the flight term alone and never touches the timezone gap; re-bracket it around the whole sum and only <b>3 of the 7</b> official cases notice — the three eastbound ones, because at multiplier <code class='inl'>1.0</code> the four westbound cases cannot tell the two readings apart. The second literal reading: <b>direction is an argument, not a deduction</b> — one official case flies −8 → +8 and is still tagged <code class='inl'>"west"</code>, so infer it from the offsets and you break a case the table looked like it was answering for you.` },
  "roommates":       { pattern: "Hashing", spot: `Two clauses in the statement point at the same container. <b>"Only with someone from the same group"</b> is a <b>group-by</b> — one pass that files every record under a key, rather than collecting the distinct groups and then re-scanning the list once per group. And <b>"paired in the order they are given"</b> says those buckets are <i>ordered</i>, which is what rules out the reflexes: do not sort anything, and prefer a <code class='inl'>Map</code> to a plain object — an object preserves insertion order only for keys that are not integer-like, so a group named <code class='inl'>"2"</code> would silently jump to the front. The last tell is not in the algorithm at all but in the <b>output format</b>: a shared room is <code class='inl'>"A and B"</code>, while a leftover person is the <b>bare name</b> — and that asymmetry is what everyone writes an <code class='inl'>if</code> for. Read it as a chunk-of-two instead, <code class='inl'>names.slice(i, i + 2).join(" and ")</code>, because <code class='inl'>slice</code> clamps at the end of the array and <code class='inl'>join</code> only puts a separator <i>between</i> elements. The odd one out then falls out of the very same expression.` },
  "ideas":           { pattern: "Direct", spot: `The thing you have to sort by <b>appears nowhere in the input</b> — every row hands you a name and three estimates, and the ranking is on a number derived from all four. That is the tell for <b>decorate → sort → undecorate</b>: compute the key <b>once per item</b>, carry it next to the item, sort on it, then throw it away. Put the arithmetic inside the comparator instead and you recompute it on every comparison, O(n log n) times rather than n. A derived key then drags two consequences behind it. It is a <b>number</b>, so the comparator must <i>subtract</i>: <code class='inl'>.sort()</code> with nothing in it stringifies each object to <code class='inl'>"[object Object]"</code>, finds every pair equal and returns the array <b>untouched</b> — the failure looks like nothing happened rather than like a wrong order. And it <b>collides far more readily than raw data does</b>: a product of two small integers ties constantly (6 × 12 and 4 × 18 are both 72), so the answer leans on <code class='inl'>sort</code> being <b>stable</b>, which it has been required to be since ES2019. Last, read the formula literally and do not tidy it. <code class='inl'>* name.length</code> is absurd — renaming a ticket cannot make the work longer — and it is <b>the factor that decides the ranking</b>, not a garnish on the estimates.` },
  "htmlextract":     { pattern: "Direct", spot: `The statement is one sentence, so the specification is really the <b>shape of a tag</b>: it opens at <code class='inl'>&lt;</code> and closes at <code class='inl'>&gt;</code>. That is a <b>region</b>, not a pattern — and the tell is that regions need <i>memory</i> while patterns don't. Carry one boolean and nesting costs nothing extra, because markup can't sit inside markup: you can never be twice inside a tag, so no counter is needed. The clause that actually separates the two readings is unwritten — a <code class='inl'>&gt;</code> inside a <b>quoted attribute value</b> is an ordinary character, which <code class='inl'>replace(/&lt;[^&gt;]*&gt;/g, "")</code> cannot know, because <code class='inl'>[^&gt;]*</code> stops at the first <code class='inl'>&gt;</code> in <i>any</i> region. Every official test keeps its <code class='inl'>&gt;</code> outside the quotes, so the one-liner passes all five and still splits <code class='inl'>&lt;a title="5 &gt; 3"&gt;</code> in the wrong place. And read what the spec does <b>not</b> ask for: no whitespace collapsing (<code class='inl'>Website.This</code> is expected run together) and no entity decoding — content is copied out exactly as it arrived.` },
  "zoning":          { pattern: "Direct", spot: `A grid, four neighbours, and the word <b>adjacent</b> — but nothing here <i>spreads</i>. A cell's verdict depends only on the up-to-4 cells touching it, so there is no region to grow, no visited set and no queue: one row-major sweep answers it, and <code class='inl'>grid[r + dr]?.[c + dc]</code> coming back <b>undefined</b> off the edge is the entire bounds check. The problem is really the <b>table</b>, and it hides two things. First, it is <b>case-sensitive</b> — <code class='inl'>"i"</code> is industrial, <code class='inl'>"I"</code> is institutional, and the table forbids them from touching; four of the five official grids contain both labels, so lower-casing one of them silently merges two zone types. Second, the answer is a list of <b>cells</b>, not of broken rules — a cell with two banned neighbours is still one coordinate, so stop at the first offender or the grader sees it twice. Then read your transcription back: every ban is <b>mirrored</b> (i↔R, i↔I, A↔C, R↔C), which means checking each cell against its own row is enough, and no city can ever have exactly one violating coordinate.` },
  "british":         { pattern: "Direct", spot: `The problem <b>prints you a table</b>, so the table is not the question — the two bullets underneath it are. <i>"Words that build on the exact spelling of a root also need to be changed"</i> is telling you the unit of replacement is the <b>root</b>, not the word, and that single line is worth <b>2 of the 5</b> official tests: anchor with <code class='inl'>\b</code> and <code class='inl'>"unrecognised"</code> and <code class='inl'>"neighbouring"</code> both come back untouched. Matching a bare substring feels reckless until you spot the control the grader planted mid-sentence — <code class='inl'>"organisation"</code> must stay British, and nothing has to enforce that, because <code class='inl'>"organise"</code> is genuinely not inside it. When a lookup key is already long and distinctive, <b>the data is its own word boundary</b>, and the affixes ride along for free precisely because they were never matched. The rest lives in the flags: <b>/g</b> because a sentence may repeat a root (<code class='inl'>str.replace(b, a)</code> silently fixes only the first), and <b>/i</b> because it may capitalise one — which then obliges you to <code class='inl'>toLowerCase()</code> on the way <i>into</i> an all-lowercase table and re-apply the capital on the way <i>out</i>.` },
  "spellcast":       { pattern: "Simulation", spot: `The printed table is the decoy — six codes, three categories, three base scores, and transcribing it feels like the whole job. The load-bearing sentence is the one underneath: <b>"each consecutive spell from a different category than the previous"</b>. That prices a spell by its <b>history</b>, not by its row in the table, so the same <code class='inl'>"f"</code> is worth 3 in one position and 18 in another and there is nothing to precompute. When a per-item value depends on the run it arrives in, stop looking for a formula and just run the sequence, carrying the two things the next item can ask about: the previous category and how long the current streak is. Then read the reset literally, because it is where the intuitive guess is wrong — a repeat does <b>not</b> zero the multiplier and does not merely fail to raise it; it sets it to <b>1</b>, since the repeating spell is the first link of the <i>next</i> chain rather than the debris of the last one. Start the multiplier at <b>0</b> against an impossible <code class='inl'>prev = ""</code> and "the first spell always scores at base value" stops being a special case and becomes the same line as everything else.` },
  "streaming":       { pattern: "Direct", spot: `The spec <b>prints you a 2×2 grid</b> and the cart items already carry both of its axes, so the pricing is one lookup — <code class='inl'>PRICES[item.format][item.type]</code> — not four <code class='inl'>if</code>s re-encoding the same table as control flow. The sentence to slow down on is the last one: <b>&quot;return the total cost rounded to two decimal places&quot;</b> rounds the <b>total</b>, which means there is exactly <i>one</i> rounding and it happens <i>after</i> the discount. Round the <b>lines</b> instead — the instinct, because a line is a price you could print on a receipt — and each one quietly drops a fraction of a cent: <code class='inl'>19.99 × 0.75</code> is <code class='inl'>14.9925</code>, so three 4K buys on premium come to <b>$44.97</b> where the answer is <b>$44.98</b>. The frightening-looking float is the <i>harmless</i> half — <code class='inl'>3.99 + 5.99 + 12.99 + 19.99</code> really is <code class='inl'>42.959999999999993747</code>, and a single <code class='inl'>toFixed(2)</code> still lands on the right cent, because that error is orders of magnitude smaller than the half-cent that decides it. Carry the mess, round it once. Then read the return format literally: <code class='inl'>&quot;$D.CC&quot;</code> is a <b>string</b> with a dollar sign on the front, so here <code class='inl'>toFixed</code> is the answer rather than the usual <code class='inl'>===</code> trap.` },
  "rental":          { pattern: "Math", spot: `Two timestamps and a per-day fee look like a duration problem, and <code class='inl'>(returned − rented) / days</code> is the trap. Read the deadline clause again: <b>"due by 12:00 PM UTC on the last day of the rental period"</b> names an <b>instant</b>, not a length — so the answer is <i>construct the deadline, then subtract</i>, and the checkout <b>time</b> drops out of the arithmetic entirely while the checkout <b>day</b> decides everything. Build it from the checkout day <b>+ tier</b> (the spec's own March 15 → March 16 example settles that it isn't <code class='inl'>tier − 1</code>) with the clock pinned to 12. Then read the two words the tests are really about: <b>"each day past"</b> is <code class='inl'>Math.ceil</code>, not <code class='inl'>floor</code> — a minute over bills a whole day — and <b>"past"</b> is strict, so <code class='inl'>overdue &gt; 0</code> makes a return at exactly 12:00:00.000 on time. Nothing says early is refunded, so the base is flat and the negative difference is simply discarded. Finally, do all of it in <code class='inl'>Date.UTC</code> / <code class='inl'>getUTC*</code> and count the money in <b>cents</b>: <code class='inl'>getDate()</code> reads the deadline in the reader's own timezone, which passes for you and fails for them.` },
  "solstice":        { pattern: "Math", spot: `The formula is handed to you, so the only decision in the problem is the word <b>even</b> — and it is not a rounding <i>mode</i>, it is a <b>grid</b>. Round onto a grid by rescaling it to the integers: <code class='inl'>Math.round(raw / 2) * 2</code>, one snap, no branch. The tell that the obvious route is wrong is that <code class='inl'>Math.round(raw)</code> answers a different question — at 66.5&deg; it returns an <b>odd</b> 21, and nudging an odd result to a neighbour is a coin flip that has already thrown away the information needed to call it. Then notice the parity is <b>load-bearing</b> rather than cosmetic: "sunrise and sunset fall symmetrically around noon" splits the leftover dark into <code class='inl'>(24 - day) / 2</code> per side, which is only a whole number of hours <i>because</i> the rounding returned an even one. An odd hour count would have no symmetric arrangement at all. The last trap is the phrase <b>"24-character string"</b> &mdash; <code class='inl'>"&#9728;&#65039;"</code> is <code class='inl'>U+2600</code> plus a variation selector, two code points, so the answer is 24 <b>hours</b>, 48 code units and somewhere in between in code points. Build it by repeating the emoji and no length ever has to agree with anything.` },
  "leet":            { pattern: "Direct", spot: `Another printed table — but this one has to be read <b>down the value column</b>, not just across the rows, and two things fall out that no amount of care with the keys would show. Two keys carry the <i>same</i> value: <code class='inl'>i</code> and <code class='inl'>l</code> both become <code class='inl'>1</code>, so eight rows hold seven values and the transform is <b>many-to-one</b>. That is worth spotting before you write anything, because it kills the obvious companion function — <code class='inl'>"547311173"</code> has <b>eight</b> possible originals, so there is no decoder to write, only a guess. The second is that one value is <code class='inl'>0</code>. A table whose values are digits is the classic place for <code class='inl'>TABLE[c] || c</code> to bite: a <b>successful</b> lookup that happens to be falsy is indistinguishable from a miss, so <code class='inl'>makeLeet("cool")</code> quietly returns <code class='inl'>"coo1"</code> and only the <code class='inl'>o</code> row is wrong. Whenever a lookup's values may legitimately be <code class='inl'>0</code>, <code class='inl'>""</code> or <code class='inl'>false</code>, the fallback must ask <i>was there an answer</i> (<code class='inl'>??</code>), not <i>was the answer interesting</i> (<code class='inl'>||</code>) — or store the values as strings, where <code class='inl'>"0"</code> is truthy and the question never arises.` },
  "bmi":             { pattern: "Direct", spot: `The recipe arrives with a <b>bare constant and no units</b> — "then multiply the result by 703" — and that is the clause to interrogate, because a magic number sitting in a physical formula is almost always a <b>unit conversion</b>. BMI is defined as kg/m<sup>2</sup>, you were handed pounds and inches, and <code class='inl'>0.45359237 / 0.0254 ** 2</code> is <code class='inl'>703.06957…</code>. Recovering that is not trivia — it tells you <b>where the constant attaches</b>. It scales the finished ratio, so <code class='inl'>weight / (height * height * 703)</code> folds it into the divisor and is wrong by a factor of 703<sup>2</sup>, while still returning a small, plausible-looking number that no eyeball catches. The second tell is the mismatch in precision: the inputs are whole numbers and the output is specified to a <b>tenth</b>. When a spec names an output precision it is telling you the last operation is a rounding — one rounding, applied to the finished result, never to the parts on the way through.` },
  "frontmatter":     { pattern: "Direct", spot: `Splitting <code class='inl'>key: value</code> lines out of a <code class='inl'>---</code> block is the part that <i>looks</i> like the problem, and it is one <code class='inl'>indexOf</code>. The real spec is the bullet underneath: <b>"Numbers, Booleans, and Strings should all be returned as their respective type"</b> — every value arrives as <b>text</b>, so something has to <b>decide what each one is</b>, and that is a <b>fallback ladder</b>. Ladders are only correct if the rung that accepts <i>everything</i> sits <b>last</b>, and the tell that these rungs are booby-trapped is sitting in the official inputs themselves. <code class='inl'>version: 1.0.0</code> punishes <code class='inl'>parseFloat</code>, which reads a <b>prefix</b> and hands back <b>1</b>, where a whole-string <code class='inl'>Number()</code> correctly refuses; <code class='inl'>url: https://example.com</code> punishes <code class='inl'>line.split(":")</code>, which shatters a value holding its own delimiter — cut at the <b>first</b> colon and slice, so the rest stays whole. The rung nothing tests for is the one worth writing down: <code class='inl'>Number("")</code> is <b>0</b>, not <code class='inl'>NaN</code>, so an empty value silently becomes the number zero unless the emptiness is checked <b>before</b> the number check. Whenever a format hands you strings and asks for types, the order of the checks <i>is</i> the algorithm.` },
};

// The clue for a challenge, or "" if none.
export const spotFor = (c) => (SPOT[c.id] && SPOT[c.id].spot) || "";
// The canonical pattern for a challenge. This table is the ONLY taxonomy —
// modules no longer carry a freeform `tag`, so an unregistered id lands on "Direct".
export const patternFor = (c) => (SPOT[c.id] && SPOT[c.id].pattern) || "Direct";
